-- Queer Atlas: Houston, Portland, Rehoboth Beach, Phoenix and Honolulu
-- Researched 2026-08-27 from official venue, organiser, public-health,
-- community-centre and destination-marketing sources.
-- Idempotent. Every entity carries its own source-backed intelligence record.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.services add column if not exists service_intel jsonb not null default '{}'::jsonb;

do $qa_require_us_qari$
begin
  if not exists (
    select 1 from public.qa_qari_profiles
    where destination_key='country:united-states' and scope_type='country' and is_published=true
  ) then
    raise exception 'Published QARI profile country:united-states is required before this city batch can run.';
  end if;
end;
$qa_require_us_qari$;

-- Complete city registry records. QARI is the published United States country
-- baseline already used by the app; the city copy does not invent a local score.
with src as (
  select * from jsonb_to_recordset($qa_us_cities$
[
  {
    "slug":"houston","name":"Houston","title":"Queer Houston","country":"United States","country_code":"US","latitude":29.7604,"longitude":-95.3698,"timezone":"America/Chicago","vibe":"big-hearted, late-night and proudly self-made",
    "local_mood":"Houston is expansive rather than walkable: Montrose still supplies the historic queer heart, while community life now stretches through Washington Avenue, Midtown and neighbourhood venues across the loop.",
    "queer_status":"A highly visible city community with deep institutions and many dedicated venues operates inside a Texas legal and political context that is materially less protective than Houston's strongest neighbourhoods.",
    "crowd_profile":"Expect a notably diverse mix of Black, Latino, Asian, immigrant, trans, lesbian, gay, leather, country-western and family communities rather than one single scene or age group.",
    "introduction":"Houston's queer map is built on scale and contrast. Montrose remains the historic gayborhood, with long-running bars, patios and leather institutions close enough for a real crawl, while Pearl Bar, Neon Boots and newer community spaces widen the geography. The Montrose Center anchors year-round care, support and organising. A good visit combines the nightlife circuit with Houston's food, museums and community calendar—and plans transport before the night begins.",
    "guide_items":[
      {"title":"About","text":"Houston has one of the South's largest and most diverse LGBTQ+ communities. Its history is visible in Montrose, but current queer life is metropolitan: nightlife, arts, health services, family events and mutual-aid networks no longer fit inside one district."},
      {"title":"Districts","text":"Start in Montrose around Pacific, Fairview and Hyde Park for the densest nightlife. Washington Avenue is home to Pearl Bar's expanded 2026 location; Downtown and Midtown hold major events, while Neon Boots requires a deliberate trip northwest."},
      {"title":"Safety","text":"Use normal large-city transport awareness, especially late at night and around isolated parking. Houston's welcoming venues do not erase Texas-level legal and political pressure affecting trans people and families; check current state guidance before travel."},
      {"title":"Nightlife","text":"JR's works as a social first stop, South Beach and Rich's provide larger dance floors, RIPCORD and Eagle serve leather and bear communities, Pearl centres women and sapphic crowds, and Neon Boots keeps country-western dance visible."},
      {"title":"Cost","text":"Covers, ride-hailing and long cross-city distances can make a night costlier than the drink prices suggest. Montrose bar-hopping reduces transport costs; hotel prices vary sharply with conventions, sports and major downtown events."}
    ],
    "guide_sources":[
      {"label":"Visit Houston LGBTQ guide","url":"https://lgbtq.visithoustontexas.com/nightlife/gay-bar-guide/"},
      {"label":"The Montrose Center","url":"https://montrosecenter.org/"},
      {"label":"HRC Municipal Equality Index","url":"https://www.hrc.org/resources/municipal-equality-index"}
    ],
    "safety_context":"Houston contains strong, public queer institutions and established nightlife, but the city sits within a fast-changing Texas policy environment. Treat municipal welcome, venue-level inclusion and state-level legal risk as three separate layers; verify current rules affecting gender-affirming care, identification and families before travel.",
    "qari_summary":"United States combines meaningful legal protection alongside remaining gaps with generally positive acceptance and uneven lived experience. Houston's large queer infrastructure improves local navigation but does not cancel Texas-specific policy risk."
  },
  {
    "slug":"portland","name":"Portland","title":"Queer Portland","country":"United States","country_code":"US","latitude":45.5152,"longitude":-122.6784,"timezone":"America/Los_Angeles","vibe":"creative, decentralised and unmistakably queer",
    "local_mood":"Queer life is woven through everyday Portland rather than confined to a single gayborhood: bars, food, art, sober groups, sports and pop-ups spread across the east side and central city.",
    "queer_status":"Portland combines strong public visibility and Oregon protections with a scene that has recently lost several legacy venues, making current calendars and community-run spaces especially important.",
    "crowd_profile":"The scene is unusually trans, non-binary, sapphic, alternative, sober-curious and multigenerational, with gay men's nightlife still present but no longer defining the whole city.",
    "introduction":"Portland feels queer at street level: in independent restaurants, art markets, women’s sports, community groups and event-led nights as much as in dedicated bars. The Q Center and Cascade AIDS Project provide durable infrastructure while venues such as Back 2 Earth, Scandals East and The Sports Bra show how the scene keeps reinventing itself. Because closures and relocations have been frequent, the current programme matters more than an old list of famous names.",
    "guide_items":[
      {"title":"About","text":"Portland has one of the country's most visible LGBTQ+ populations and a long tradition of queer organising, independent business and cultural experimentation. The contemporary scene is distributed, event-led and broader than a conventional gay-bar circuit."},
      {"title":"Districts","text":"North Mississippi holds the Q Center; Alberta and Martin Luther King Jr Boulevard host current queer gathering spaces; inner southeast has queer food and performance; Old Town and downtown retain several gay nightlife institutions."},
      {"title":"Safety","text":"Oregon offers comparatively strong legal protection, but harassment and hate incidents remain possible. Late-night transport, weather, consent and houselessness-related street conditions deserve ordinary awareness without treating vulnerable residents as a threat."},
      {"title":"Nightlife","text":"Choose by programme: queer and trans DJ nights, drag, leather events, women’s sports, karaoke and sober groups draw different communities. Verify the same-day calendar because Portland's strongest queer night may be a pop-up rather than a permanent club."},
      {"title":"Cost","text":"Public transport and relatively compact inner neighbourhoods can control costs, although ride-hailing rises late. Many community programmes are free or sliding-scale; ticketed dance events and weekend accommodation carry the larger premium."}
    ],
    "guide_sources":[
      {"label":"Travel Portland LGBTQ guide","url":"https://www.travelportland.com/culture/gay-portland/"},
      {"label":"Portland Q Center","url":"https://www.pdxqcenter.org/"},
      {"label":"Oregon LGBTQ resources","url":"https://www.oregon.gov/oha/ph/healthypeoplefamilies/youth/pages/lgbtq-resources.aspx"}
    ],
    "safety_context":"Portland's visible community and Oregon protections support ordinary openness, but safety still varies by setting and identity. Use current venue calendars, confirm late-night routes, and do not mistake the closure of a famous bar for disappearance of the wider trans, sapphic, sober and event-led community.",
    "qari_summary":"United States combines meaningful legal protection alongside remaining gaps with generally positive acceptance and uneven lived experience. Oregon protections and Portland's visible community lower local friction, while harassment and federal or national changes remain relevant."
  },
  {
    "slug":"rehoboth_beach","name":"Rehoboth Beach","title":"Queer Rehoboth Beach","country":"United States","country_code":"US","latitude":38.7209,"longitude":-75.0760,"timezone":"America/New_York","vibe":"compact, coastal and proudly multigenerational",
    "local_mood":"A small beach town with an outsized queer identity: Baltimore Avenue, Poodle Beach and CAMP Rehoboth create an easy social triangle that becomes much busier on summer and holiday weekends.",
    "queer_status":"Rehoboth is a long-established LGBTQ+ resort destination with visible civic recognition, dedicated nightlife and year-round community infrastructure rather than a seasonal rainbow marketing exercise.",
    "crowd_profile":"Summer brings Washington, Baltimore and Philadelphia visitors, gay men, queer women, couples and multigenerational friend groups; quieter months reveal a close year-round coastal community.",
    "introduction":"Rehoboth Beach compresses a surprising amount of queer life into a walkable seaside centre. Poodle Beach supplies the daytime landmark, Baltimore Avenue holds bars, restaurants and CAMP Rehoboth, and larger dance or fundraising events extend the season beyond midsummer. It is more mixed and smaller than Provincetown or Fire Island, but its civic visibility, community centre and long-running destination culture make it one of the Mid-Atlantic's most dependable queer escapes.",
    "guide_items":[
      {"title":"About","text":"Queer visitors have shaped Rehoboth for generations. The city now publicly recognises that history, while CAMP Rehoboth, dedicated nightlife and recurring cultural events connect tourism with a functioning year-round community."},
      {"title":"Districts","text":"Baltimore Avenue is the compact nightlife and community spine. Poodle Beach is reached at the south end of the boardwalk near Queen Street, while Diego's sits farther along Rehoboth Avenue and usually requires a walk, bicycle or short ride."},
      {"title":"Safety","text":"The central resort area is generally busy and legible, but beach conditions, heat, alcohol, dark side streets and seasonal traffic still matter. Delaware protections are stronger than in many nearby states; venue accessibility varies in older buildings."},
      {"title":"Nightlife","text":"Blue Moon and The Pines combine dinner with entertainment, Aqua is strongest after the beach, Freddie's leans colourful and karaoke-led, and Diego's supplies a larger late-night dance setting. Schedules change significantly by season."},
      {"title":"Cost","text":"Accommodation and parking peak on summer, Pride and Labor Day weekends. Walking between the beach and Baltimore Avenue saves transport costs; booking lodging early matters more here than finding a cheap drink special."}
    ],
    "guide_sources":[
      {"label":"City of Rehoboth Beach LGBTQ page","url":"https://www.rehobothbeachde.gov/experience-rehoboth-beach/pride/"},
      {"label":"Visit Rehoboth LGBTQ guide","url":"https://www.visitrehoboth.com/things-to-do/lgbtq-guide-to-rehoboth-beach"},
      {"label":"CAMP Rehoboth","url":"https://www.camprehoboth.com/"}
    ],
    "safety_context":"Central Rehoboth is a visible queer resort environment with strong community infrastructure. Seasonal crowding, water conditions, heat and impaired driving are more common practical risks than identity concealment; outside the resort core, do not assume every part of Sussex County shares the same level of visibility.",
    "qari_summary":"United States combines meaningful legal protection alongside remaining gaps with generally positive acceptance and uneven lived experience. Delaware protections and Rehoboth's long-established queer civic culture create a comparatively lower-friction local destination."
  },
  {
    "slug":"phoenix","name":"Phoenix","title":"Queer Phoenix","country":"United States","country_code":"US","latitude":33.4484,"longitude":-112.0740,"timezone":"America/Phoenix","vibe":"desert-bright, social and built around chosen family",
    "local_mood":"The Melrose Curve gives Phoenix a recognisable gayborhood, but the wider queer community moves between central-city bars, drag stages, youth organisations, sports and event-led spaces across the Valley.",
    "queer_status":"Phoenix has durable municipal inclusion, major LGBTQ+ institutions and visible nightlife, while Arizona's state context remains mixed and can change faster than a tourism guide.",
    "crowd_profile":"Latin, Indigenous, trans, lesbian, gay, leather, country-western, drag and younger community networks overlap, with different venues carrying genuinely different audiences rather than one citywide default.",
    "introduction":"Phoenix's clearest queer orientation point is the one-mile Melrose District along Seventh Avenue, where bars, murals, restaurants and rainbow storefronts create a rare walkable cluster in a car-led metropolis. Charlie's adds a large country-and-dance institution nearby, while the Southwest Center and one-n-ten anchor health and youth support. Heat changes the rhythm: major Pride celebrations move to autumn, patios come alive after sunset, and transport planning is part of a safe night out.",
    "guide_items":[
      {"title":"About","text":"Phoenix supports a large, diverse LGBTQ+ population across a sprawling metropolitan area. The Melrose District supplies a visible core, while community services, drag, sport and nightlife extend through central Phoenix and the wider Valley."},
      {"title":"Districts","text":"Use Seventh Avenue between Indian School and Camelback as the Melrose starting point. Charlie's is near Camelback Road; Kobalt and the Southwest Center sit closer to Central Avenue. Distances become car-scale quickly outside these clusters."},
      {"title":"Safety","text":"Extreme heat is a primary travel risk, even after dark. Carry water, limit long summer walks and plan a sober ride. Phoenix protections and venue culture should be considered separately from changing Arizona state policy affecting trans people."},
      {"title":"Nightlife","text":"Boycott centres sapphic nights, The Rock and Stacy's mix drag and karaoke, Kobalt is performance-led, Charlie's combines country roots with a large dance floor, and Anvil serves a more specialised leather and fetish audience."},
      {"title":"Cost","text":"Drinks and covers vary, but transport across the Valley is the hidden expense. Staying near Central Avenue or Melrose reduces ride costs; autumn Pride weekends and major sports events increase room rates."}
    ],
    "guide_sources":[
      {"label":"Visit Phoenix Melrose guide","url":"https://www.visitphoenix.com/lgbtq/melrose-district/"},
      {"label":"Visit Phoenix LGBTQ-owned businesses","url":"https://www.visitphoenix.com/lgbtq/lgbtq-owned-businesses/"},
      {"label":"Southwest Center","url":"https://www.swcenter.org/"}
    ],
    "safety_context":"Phoenix's community infrastructure and municipal protections are meaningful, but heat, long driving distances and Arizona-level policy changes affect real travel decisions. Confirm outdoor-event conditions, use planned transport after drinking and check current legal guidance for trans travellers rather than relying on an old state reputation.",
    "qari_summary":"United States combines meaningful legal protection alongside remaining gaps with generally positive acceptance and uneven lived experience. Phoenix's municipal inclusion and strong institutions improve local navigation, while Arizona's mixed state policy context remains relevant."
  },
  {
    "slug":"honolulu","name":"Honolulu","title":"Queer Honolulu","country":"United States","country_code":"US","latitude":21.3069,"longitude":-157.8583,"timezone":"Pacific/Honolulu","vibe":"island-rooted, welcoming and proudly visible",
    "local_mood":"Waikīkī concentrates visitor nightlife and Pride, while local queer life also runs through Native Hawaiian and Pacific identities, health organisations, community groups and neighbourhood networks beyond the resort strip.",
    "queer_status":"Honolulu pairs strong Hawaiʻi protections and high public visibility with a living māhū and MVPFAFF+ context that should be understood as culture, not reduced to a tourism label.",
    "crowd_profile":"Local kānaka maoli and Pacific communities, Asian American residents, military-connected people, trans and queer youth, mainland visitors and international tourists meet in a scene that changes sharply between Waikīkī and local spaces.",
    "introduction":"Honolulu offers a compact visitor-facing queer circuit around Waikīkī, led by Hula's, Bacchus and Wang Chung's, plus the larger Scarlet club downtown. Its deeper value comes from Hawaiʻi's own histories of gender and sexuality and from organisations such as the Hawaiʻi LGBT Legacy Foundation and HHHRC. October's Honolulu Pride is the major annual gathering. Respectful visitors should look beyond beach nightlife, learn the meaning of māhū and MVPFAFF+, and recognise that local community is not a resort accessory.",
    "guide_items":[
      {"title":"About","text":"Honolulu's LGBTQ+ life combines visitor-facing Waikīkī nightlife with Native Hawaiian and Pacific understandings of gender and sexuality, long-running health organisations, local activism and an October Pride season."},
      {"title":"Districts","text":"Waikīkī holds Hula's, Bacchus, Wang Chung's, Queen's Surf and many Pride events. Scarlet is in Chinatown/Downtown, while healthcare and community services sit around Ala Moana, King Street, Diamond Head and central Honolulu."},
      {"title":"Safety","text":"Hawaiʻi has comparatively strong protections, but ocean conditions, sun, dehydration, theft from beaches and impaired late-night travel are practical risks. Respect local culture and do not treat māhū identity as entertainment or exotic vocabulary."},
      {"title":"Nightlife","text":"Hula's moves from daytime views into shows and dancing, Bacchus is a compact upstairs bar, Wang Chung's centres karaoke, and Scarlet provides the largest club production. Pride weekend adds official parties across Waikīkī."},
      {"title":"Cost","text":"Honolulu is expensive: hotels, resort fees, parking and food dominate the budget. Waikīkī's walkability can reduce rides; public buses help, but late-night schedules and island travel times should be checked in advance."}
    ],
    "guide_sources":[
      {"label":"Go Hawaiʻi LGBTQ guide","url":"https://www.gohawaii.com/experiences/lgbtqia"},
      {"label":"Honolulu Pride","url":"https://www.honolulupride.com/"},
      {"label":"Hawaiʻi LGBTQ+ Commission","url":"https://humanservices.hawaii.gov/lgbtq-commission/"}
    ],
    "safety_context":"Honolulu has strong visible community infrastructure and comparatively protective state law. Practical visitor risks centre on heat, ocean conditions, beach theft and alcohol-related travel. Cultural safety also matters: use Native Hawaiian gender language respectfully and follow local organisations rather than projecting mainland categories onto Hawaiʻi.",
    "qari_summary":"United States combines meaningful legal protection alongside remaining gaps with generally positive acceptance and uneven lived experience. Hawaiʻi protections and Honolulu's visible community lower local friction, while cost, island logistics and ordinary visitor safety remain material."
  }
]
$qa_us_cities$) c(
  slug text,name text,title text,country text,country_code text,latitude double precision,longitude double precision,timezone text,vibe text,
  local_mood text,queer_status text,crowd_profile text,introduction text,guide_items jsonb,guide_sources jsonb,safety_context text,qari_summary text
)
)
insert into public.qa_cities (
  slug,name,title,country,country_code,latitude,longitude,map_confirmed,timezone,vibe,local_mood,queer_status,crowd_profile,introduction,
  guide_items,guide_sources,guide_checked_at,safety_context,qari_destination_key,qari_score,qari_summary,qari_confidence,status,updated_at
)
select c.slug,c.name,c.title,c.country,c.country_code,c.latitude,c.longitude,true,c.timezone,c.vibe,c.local_mood,c.queer_status,c.crowd_profile,c.introduction,
       c.guide_items,c.guide_sources,date '2026-08-27',c.safety_context,q.destination_key,q.qari_score,q.summary,q.confidence,'published',timezone('utc',now())
from src c
cross join lateral (
  select destination_key,qari_score,summary,confidence
  from public.qa_qari_profiles
  where destination_key='country:united-states' and scope_type='country' and is_published=true
  order by reviewed_at desc nulls last
  limit 1
) q
on conflict (slug) do update set
  name=excluded.name,title=excluded.title,country=excluded.country,country_code=excluded.country_code,latitude=excluded.latitude,longitude=excluded.longitude,
  map_confirmed=true,timezone=excluded.timezone,vibe=excluded.vibe,local_mood=excluded.local_mood,queer_status=excluded.queer_status,
  crowd_profile=excluded.crowd_profile,introduction=excluded.introduction,guide_items=excluded.guide_items,guide_sources=excluded.guide_sources,
  guide_checked_at=excluded.guide_checked_at,safety_context=excluded.safety_context,qari_destination_key=excluded.qari_destination_key,
  qari_score=excluded.qari_score,qari_summary=excluded.qari_summary,qari_confidence=excluded.qari_confidence,status='published',updated_at=excluded.updated_at;

-- Places: no directory filler. Each entry has a current official or official-tourism
-- source and individual operational intelligence.
with src as (
  select * from jsonb_to_recordset($qa_us_places$
[
  {"name":"JR's Bar & Grill","city":"houston","type":"bar","description":"A Montrose institution since 1982, JR's combines several bars, a courtyard patio, karaoke, drag and a come-as-you-are social rhythm. It is usually a better first stop for conversation than the neighbouring dance club, and the official Houston guide still treats it as a core piece of the Pacific Street circuit.","vibe":"classic gay social bar with karaoke, patio conversation and multigenerational Houston energy","hours":"Daily; karaoke Wednesdays, Thursdays and Sundays. Verify holiday and Pride schedules on the official channel.","link":"https://www.jrsbarandgrill.com/","location":"808 Pacific Street, Houston, TX 77006, United States","lat":29.74775,"lng":-95.39046,"intel":{"queue_wait":"Ordinary afternoons and early evenings are easy; Pride and late karaoke create a patio and bar bottleneck rather than a formal velvet-rope line.","best_nights":"Wednesday, Thursday and Sunday centre karaoke; major drag and Pride programmes change the room, while early evening is best for an unhurried first visit.","crowd_mix":"Gay men remain the visible core, joined by queer locals, visitors, drag audiences and long-time Montrose regulars across a wider age range than a single dance club.","dress_code":"Casual Houston bar clothes work: denim, trainers, shorts and expressive Pride looks. Bring valid identification and dress for heat on the courtyard patio.","staff_inclusivity":"More than four decades as a dedicated LGBTQ+ venue and an active queer programme provide direct institutional evidence; accessibility details should still be confirmed for a specific need.","review_signal":"Official destination coverage consistently distinguishes the relaxed patio and karaoke identity from South Beach next door; choose it for social energy, not a giant dance production.","source_urls":["https://lgbtq.visithoustontexas.com/listings/jr%E2%80%99s-bar-and-grill/30190/","https://lgbtq.visithoustontexas.com/nightlife/weekly-circuit/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"South Beach Houston","city":"houston","type":"club","description":"The large dance-floor counterpart to JR's on Pacific Street, South Beach runs pop-forward club nights beneath a signature chandelier and opens onto a substantial rear patio. Complimentary early admission and later cover rules are programme-dependent, so the official night listing matters more than old directory hours.","vibe":"high-production gay dance club with a big floor, pop energy and a cooling patio","hours":"Night and event-led; complimentary admission is commonly advertised before 22:00. Confirm the current programme and cover.","link":"https://southbeachhouston.com/","location":"810 Pacific Street, Houston, TX 77006, United States","lat":29.74772,"lng":-95.39038,"intel":{"queue_wait":"The easiest arrival is before the advertised free-entry cutoff; Pride, headline DJs and the midnight peak can produce a real door and coat-check wait.","best_nights":"Friday and Saturday deliver the full chandelier-and-dance-floor version; Pride and named DJ nights are bigger but also denser and less conversational.","crowd_mix":"Young and midlife gay men, visiting circuit crowds, drag fans, queer friends and allies dominate, with more tourists than the quieter Montrose neighbourhood bars.","dress_code":"Club-casual and body-confident looks are common, but no verified formal fashion code is published. Use secure pockets and bring government-issued ID.","staff_inclusivity":"The venue is explicitly LGBTQ+ and deeply connected to Houston Pride nightlife; door, accessibility and bag policies should be checked directly for major events.","review_signal":"Official Houston guidance positions South Beach as the large dance choice and repeatedly highlights the rear patio; visitors seeking conversation should start elsewhere and arrive later.","source_urls":["https://lgbtq.visithoustontexas.com/nightlife/gay-bar-guide/","https://lgbtq.visithoustontexas.com/nightlife/a-montrose-pub-crawl/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"RIPCORD","city":"houston","type":"bar","description":"Operating since 1980, RIPCORD is Texas's oldest leather bar and a durable Montrose home for bears, leather, fetish and masculine-of-centre gay subcultures. The large patio softens the specialist identity, while the adjoining leather shop on weekend nights makes the venue's community role unusually concrete.","vibe":"historic leather bar with an unpretentious patio and a broad bear-and-fetish community","hours":"Monday-Saturday 13:00-02:00; Sunday 12:00-02:00 according to current official tourism listing.","link":"https://www.ripcordhouston.com/","location":"715 Fairview Street, Houston, TX 77006, United States","lat":29.74707,"lng":-95.38922,"intel":{"queue_wait":"Most nights use a simple ID check with little queue; Pride, leather weekends and patio events can compress the Fairview entrance after 22:00.","best_nights":"Friday and Saturday activate the leather shop and fullest crowd, while Sunday afternoon gives a lower-pressure patio introduction to the institution.","crowd_mix":"Bears, cubs, daddies, leather and fetish communities lead, with gay men of varied ages and curious respectful visitors; it is specialist without being costume-compulsory.","dress_code":"Everyday casual clothes are accepted unless an event states otherwise. Leather, harnesses and fetish gear are welcome, not mandatory; consent and no-photo expectations matter more than fashion.","staff_inclusivity":"The venue's long LGBTQ+ history and explicit community scope are strong evidence. Inclusion is audience-specific, and guests should respect themed-event boundaries and published rules.","review_signal":"Current official tourism material consistently frames the patio as approachable and the leather identity as real; arrive with respect rather than treating the bar as spectacle.","source_urls":["https://lgbtq.visithoustontexas.com/listings/ripcord/22430/","https://lgbtq.visithoustontexas.com/nightlife/gay-bar-guide/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Eagle Houston","city":"houston","type":"bar","description":"A multi-level Montrose bar connecting leather and bear traditions with karaoke, pop and electronic dance floors, a deck and a sociable patio. The different levels can feel like separate venues, making Eagle useful for groups who want both conversation and dancing without committing to one music lane.","vibe":"leather-rooted multi-level gay bar where patio socialising meets pop and electronic dancing","hours":"Daily and event-led; Sunday afternoon is a published social anchor. Verify exact hours and themed access.","link":"https://eaglehouston.com/","location":"611 Hyde Park Boulevard, Houston, TX 77006, United States","lat":29.74733,"lng":-95.38842,"intel":{"queue_wait":"Ordinary entry is straightforward, but Pride and major leather events create a line and crowded stairs; Sunday afternoon usually builds gradually rather than all at once.","best_nights":"Sunday from late afternoon is the clearest patio-and-balcony social ritual; Friday and Saturday bring stronger dancing and event-specific leather or bear energy.","crowd_mix":"Bears, leather men, jocks, gay neighbourhood regulars, DJs and visitors mix across floors; moving between levels changes both music and age profile.","dress_code":"Casual clothes are normal, with leather, sportswear and fetish looks increasing on themed nights. Check event rules and keep footwear practical for stairs.","staff_inclusivity":"A dedicated LGBTQ+ identity and recurring leather, bear and Pride programmes are documented. Multi-level access may be a physical limitation and should be confirmed before travel.","review_signal":"Houston's official guide repeatedly separates the sociable deck and patio from the busier upstairs pop floor and downstairs electronic sound—use that layout deliberately.","source_urls":["https://lgbtq.visithoustontexas.com/nightlife/gay-bar-guide/","https://lgbtq.visithoustontexas.com/nightlife/weekly-circuit/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Pearl Bar Houston","city":"houston","type":"bar","description":"One of Texas's very few bars centred on lesbians and queer women, Pearl moved in June 2026 to a much larger Washington Avenue site with two club rooms, an outdoor event area, kitchen, women-centred sports bar and members-only speakeasy. Use the new address, not the former location still copied by older directories.","vibe":"large sapphic nightlife campus balancing dancing, sport, performances and outdoor community","hours":"Programme-led at the new 2026 venue; check the official calendar for room, ticket and membership requirements.","link":"https://www.pearlbarhouston.com/","location":"2811 Washington Avenue, Houston, TX 77007, United States","lat":29.77005,"lng":-95.39492,"intel":{"queue_wait":"The larger 2026 site has dedicated parking and more capacity, but opening weekends, concerts and major sapphic parties can still create a ticket-check rush.","best_nights":"Choose the format: Tuesday karaoke, drag-king and women’s-sport programmes feel different from DJ and concert nights in the larger club rooms.","crowd_mix":"Lesbians, queer women, non-binary guests, trans community, sapphic visitors and friends are centred; the venue is welcoming beyond that core without losing its purpose.","dress_code":"No single code fits the multi-room programme. Casual sports-bar clothes, dance looks and expressive queer fashion all work; check any ticketed theme separately.","staff_inclusivity":"Women-centred ownership and programming provide direct evidence of mission. The move added safer parking and multiple room options, but specific accessibility needs should be confirmed.","review_signal":"The important current signal is structural: the official 2026 move expanded from a beloved bar into a multi-format venue rather than merely changing street address.","source_urls":["https://www.visithoustontexas.com/lgbtq/post/pride-month-in-houston/","https://lgbtq.visithoustontexas.com/nightlife/gay-bar-guide/"],"research_status":"official_2026_relocation_verified","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Neon Boots Dancehall & Saloon","city":"houston","type":"club","description":"A 10,000-square-foot LGBTQ+ country-western dance hall northwest of central Houston, with a large floor, line and two-step lessons, karaoke, Latin nights, live shows and several bars. The historic Esquire Ballroom setting and distance from Montrose make this a planned destination rather than an accidental crawl stop.","vibe":"big queer honky-tonk with two-step lessons, line dancing, karaoke and Latin nights","hours":"Weekly programme-led; verify lesson, karaoke and live-show times before making the cross-city trip.","link":"https://neonbootsclub.com/","location":"11410 Hempstead Road, Houston, TX 77092, United States","lat":29.80556,"lng":-95.48174,"intel":{"queue_wait":"The large building absorbs ordinary crowds, but special concerts and Pride programmes create parking and ticket delays; arrive before a lesson if you want floor orientation.","best_nights":"Pick line dancing, partner lessons, Latin night or a live show according to interest. Karaoke runs on several published weeknights and weekend dates.","crowd_mix":"Country-western gay men, lesbians, Latin-night dancers, beginners, experienced two-steppers and mixed-age local groups share the unusually large floor.","dress_code":"Boots and western wear fit but are not compulsory. Choose smooth, secure dance footwear; hats and themed looks should never override floor etiquette or consent.","staff_inclusivity":"The club is explicitly LGBTQ+ and provides structured lessons that lower the entry barrier for newcomers. Ask ahead about partner rotation and mobility accommodation.","review_signal":"Official Houston guidance highlights both scale and distance: it is the city's dedicated queer country destination, not an extension of the walkable Montrose circuit.","source_urls":["https://lgbtq.visithoustontexas.com/nightlife/gay-bar-guide/","https://lgbtq.visithoustontexas.com/nightlife/weekly-circuit/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Barcode Houston","city":"houston","type":"bar","description":"A small Fairview Street gay dive with a compact stage, patio, recurring drag and Tuesday karaoke. Barcode is deliberately less polished than Houston's mega-clubs; its value is a close local room where performers and regulars are visible rather than swallowed by production.","vibe":"compact gay dive for close-up drag, karaoke and an easy neighbourhood patio","hours":"Daily programme varies; Tuesday karaoke is published 21:00-00:00. Verify show times on the current channel.","link":"https://www.facebook.com/BarcodeHouston/","location":"817 Fairview Street, Houston, TX 77006, United States","lat":29.74692,"lng":-95.39043,"intel":{"queue_wait":"There is rarely a formal line, but the small room can feel full quickly during drag; arrive before showtime if sightlines or patio seating matter.","best_nights":"Tuesday karaoke provides the clearest recurring format, while the stacked drag calendar is the reason to check a specific performer rather than default to Saturday.","crowd_mix":"Montrose regulars, drag audiences, karaoke singers, gay men and queer friends fill a more local, intimate room than the larger Pacific Street venues.","dress_code":"Very casual dive-bar clothing is normal. Bring small bills for performers, valid ID and weather awareness for time spent on the patio.","staff_inclusivity":"A dedicated gay identity and recurring local drag programme are directly documented. The compact layout may limit mobility and sightlines; ask before a busy show.","review_signal":"Official tourism calls Barcode a small local shack and distinguishes its drag from restaurant-style productions; that intimacy is the feature, not a lack of polish.","source_urls":["https://lgbtq.visithoustontexas.com/listings/barcode/30639/","https://lgbtq.visithoustontexas.com/nightlife/gay-bar-guide/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"George Country Sports Bar","city":"houston","type":"bar","description":"A relaxed Fairview Street gay bar built around sport screens, pool, darts, weekday food specials and country music rather than a permanent dance-floor spectacle. George is useful as a low-pressure Montrose anchor and a practical first stop before the denser late-night circuit.","vibe":"easy gay sports bar with country flavour, pool, darts and neighbourhood regulars","hours":"Monday-Saturday according to current official tourism guide; verify Sunday and event openings directly.","link":"https://www.facebook.com/GeorgeCountrySportsBar/","location":"617 Fairview Street, Houston, TX 77006, United States","lat":29.74720,"lng":-95.38849,"intel":{"queue_wait":"Entry is normally immediate; game finals, steak night and Pride can fill tables without producing a formal club queue.","best_nights":"Thursday steak night and Friday taco night add a local ritual, while televised sports determine when the otherwise calm room becomes animated.","crowd_mix":"Gay sports fans, country listeners, pool and darts players, older Montrose regulars and low-key visitors create a conversational, mostly local crowd.","dress_code":"Sports jerseys, denim, boots, shorts and everyday bar clothes fit. No published fashion code; bring valid identification and settle in rather than dressing for a circuit floor.","staff_inclusivity":"Its longstanding gay identity and community routine are documented by Houston's official LGBTQ guide. Accessibility and food-service details should be checked directly.","review_signal":"Official destination material consistently presents George as the chill country-sports alternative in the Montrose crawl, especially useful before louder venues.","source_urls":["https://lgbtq.visithoustontexas.com/nightlife/gay-bar-guide/","https://lgbtq.visithoustontexas.com/nightlife/a-montrose-pub-crawl/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Back 2 Earth","city":"portland","type":"bar","description":"A queer bar on Martin Luther King Jr Boulevard built around DJs, karaoke, drag, open mics, meetups and community events rather than one fixed club identity. The official schedule warns that quiet nights may close early, so a named event is the key to experiencing the room at full signal.","vibe":"cosmic neighbourhood queer bar with low-pressure games, karaoke and event-led dancing","hours":"Tuesday-Thursday 19:00-01:00; Friday-Saturday 19:00-02:00; closed Sunday-Monday. Quiet nights may close early.","link":"https://www.back2earthpdx.com/","location":"3536 NE Martin Luther King Jr Boulevard, Portland, OR 97212, United States","lat":45.54876,"lng":-122.66139,"intel":{"queue_wait":"Most regular nights are walk-in friendly; a popular DJ, drag show or community collaboration can fill the small room, so ticket guidance should control arrival.","best_nights":"Choose a published karaoke, queer DJ, drag or meetup date. Friday and Saturday run latest, but an organised weekday often has more distinct community character.","crowd_mix":"Queer women, trans and non-binary guests, gay men, performers, creatives and neighbourhood regulars mix in a deliberately broad community room.","dress_code":"Casual, expressive Portland clothing fits; themed looks are invitations rather than requirements. Dress for a compact dancing room and changing rain outside.","staff_inclusivity":"The venue publicly calls itself a queer space and actively invites community collaborations and meetups. Contact management in advance for access or event-specific needs.","review_signal":"Current official operation is clear, including the unusual early-close warning. That transparency means visitors should follow the live event rather than assume every open night becomes a party.","source_urls":["https://www.back2earthpdx.com/","https://www.travelportland.com/culture/gay-portland/"],"research_status":"official_current_operation","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Scandals East","city":"portland","type":"bar","description":"The continuing Alberta Arts District chapter of the Scandals name after the original downtown bar closed in September 2025. Its relevance is current, not nostalgic: a smaller east-side LGBTQ+ social bar carrying forward community programming while the old Pink Triangle address should no longer appear in live recommendations.","vibe":"intimate east-side continuation of a Portland gay-bar legacy, focused on community over scale","hours":"Event-led; verify the current Scandals East schedule and do not use the closed downtown location's hours.","link":"https://www.scandalspdx.com/","location":"2936 NE Alberta Street, Portland, OR 97211, United States","lat":45.55888,"lng":-122.63521,"intel":{"queue_wait":"The smaller room is generally easy early and capacity-sensitive during named events; there is no reason to queue at the permanently closed downtown address.","best_nights":"Use the current event calendar. Community gatherings and programmed evenings matter more than applying the former downtown bar's famous weekend rhythm to this location.","crowd_mix":"Long-time Scandals regulars, Alberta neighbours, gay men and a broader east-side queer community meet in a more intimate setting than the original venue.","dress_code":"Casual neighbourhood-bar clothes are appropriate. Confirm any event theme directly and bring weather protection for Alberta Street travel.","staff_inclusivity":"The operation explicitly continues an LGBTQ+ institution, while relocation means access and layout assumptions from the old bar are invalid and must be rechecked.","review_signal":"Travel Portland explicitly confirms the 2025 downtown closure and identifies Scandals East as the live continuation—the key quality signal is correct location data.","source_urls":["https://www.travelportland.com/culture/gay-portland/","https://www.scandalspdx.com/"],"research_status":"official_relocation_status_verified","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"CC Slaughters","city":"portland","type":"club","description":"A long-running Old Town gay bar and dance venue whose current calendar spans queer and trans EDM, live-band karaoke, drag, bingo and visiting performers. Its 2025 closure announcement did not become a permanent shutdown; the active official site and 2026 programming are the correct current signals.","vibe":"legacy gay club with drag, live music, karaoke and queer-trans electronic nights","hours":"Daily from approximately 15:00 until 02:00 according to the current official hours page; verify event doors.","link":"https://ccslaughterspdx.com/","location":"219 NW Davis Street, Portland, OR 97209, United States","lat":45.52450,"lng":-122.67297,"intel":{"queue_wait":"Early bar hours are easy; headline drag, Pride and Saturday dance programming can create a door line and compressed Old Town pavement.","best_nights":"Use the calendar: queer-trans EDM, live-band karaoke, Safari productions and bingo serve different audiences. Saturday is not automatically the best fit for everyone.","crowd_mix":"Gay men, drag audiences, trans and queer DJs, tourists, karaoke regulars and Old Town nightlife visitors share a venue whose crowd changes sharply by programme.","dress_code":"Club-casual and expressive looks are common with no verified standing fashion code. Bring ID, secure valuables and check event-specific bag rules.","staff_inclusivity":"Dedicated LGBTQ+ operation and explicitly queer-trans bookings provide direct evidence. Old Town context and venue layout make access planning sensible before a major event.","review_signal":"The live 2026 official calendar resolves conflicting 2025 closure reports. Current programming, not an old announcement or directory status, supports inclusion.","source_urls":["https://ccslaughterspdx.com/","https://ccslaughterspdx.com/hours/"],"research_status":"official_2026_operation_verified","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"The Sports Bra","city":"portland","type":"bar","description":"The women-owned sports bar that changed the national conversation by showing women's sport on every screen. It is not a lesbian bar by formal category, but queer ownership, women-centred programming and a broad community following make it a major sober-optional, food-led social option beyond traditional nightlife.","vibe":"joyful women’s-sports community bar where queer ownership and all-ages fandom lead","hours":"Game and service schedule varies; reservations or early arrival are wise for major women's sports fixtures.","link":"https://thesportsbrapdx.com/","location":"2512 NE Broadway, Portland, OR 97232, United States","lat":45.53472,"lng":-122.63985,"intel":{"queue_wait":"Ordinary service is manageable, but major women's finals and Portland Thorns or basketball fixtures can fill seats well before play begins.","best_nights":"The best visit follows the women’s sport you care about, not a nightclub weekday. Official watch parties produce the fullest communal atmosphere.","crowd_mix":"Queer women, women’s-sports fans, families, athletes, trans and non-binary guests and allies create an unusually intergenerational bar-and-restaurant crowd.","dress_code":"Team colours, casual clothes and everyday restaurant attire fit. It is an all-ages food setting at many times, not a fashion-gated club.","staff_inclusivity":"Queer and woman ownership, a women’s-sport-only screen policy and documented community giving provide stronger evidence than a generic friendly label.","review_signal":"Travel Portland's current feature emphasises both national significance and everyday local community; event-day demand is the practical caveat to an otherwise approachable room.","source_urls":["https://www.travelportland.com/culture/the-sports-bra/","https://thesportsbrapdx.com/"],"research_status":"official_plus_destination_feature","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Eagle Portland","city":"portland","type":"bar","description":"A North Lombard leather and bear bar with a neighbourhood scale, patio and event-driven calendar. The Eagle name signals a gay men's leather tradition, but the practical experience depends on the exact social, gear night or fundraiser rather than a permanent costume threshold.","vibe":"north Portland leather-and-bear bar with patio ease and community event nights","hours":"Event-led; verify the official calendar, cover, audience and consent rules before travelling north.","link":"https://www.eagleportland.com/","location":"835 N Lombard Street, Portland, OR 97217, United States","lat":45.57716,"lng":-122.67503,"intel":{"queue_wait":"Regular social nights rarely need a long queue; major leather weekends, fundraisers and capacity events can create a concentrated ID check.","best_nights":"Choose a listed bear, leather, gear or community fundraiser event. A quiet patio visit and a packed themed night are fundamentally different experiences.","crowd_mix":"Gay and bisexual men, bears, leather community, trans men and respectful friends form the core; event descriptions should guide whether a night has narrower boundaries.","dress_code":"Casual clothes are normally accepted unless the event states gear requirements. Leather and fetish wear are welcome; consent and photography rules outrank appearance.","staff_inclusivity":"The venue's dedicated community identity is direct evidence, but inclusion is event-specific rather than universal. Ask about gender, access and changing-space rules when relevant.","review_signal":"The strongest planning signal is programme precision: specialist events deserve accurate audience labels, while an ordinary bar night should not be sensationalised.","source_urls":["https://www.eagleportland.com/","https://www.travelportland.com/culture/gay-portland/"],"research_status":"official_current_programme","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"STAG PDX","city":"portland","type":"club","description":"An adults-only gay nightclub in Old Town built around male revue performance, drag, DJs and late dance energy. STAG is entertainment-led and audience-specific rather than a general community bar; check the exact show and ticket conditions before assuming the room's tone.","vibe":"adult gay nightclub mixing male revue, drag and late-night dancing in Old Town","hours":"Night and event-led; use the official ticket and calendar page for doors, age and cover.","link":"https://www.stagpdx.com/","location":"317 NW Broadway, Portland, OR 97209, United States","lat":45.52506,"lng":-122.67771,"intel":{"queue_wait":"Ticketed revue and Pride nights create the strongest arrival rush; buy ahead and allow time for Old Town parking or transit.","best_nights":"Select a named male revue, drag production or DJ night. The show format determines whether the evening feels seated, interactive or primarily dance-focused.","crowd_mix":"Gay men, bachelorette and mixed celebration groups, drag audiences and tourists dominate; the adult entertainment focus is more specific than Portland's broad queer bars.","dress_code":"Night-out casual and expressive club looks fit, with valid ID essential. Respect performer boundaries and any phone or tipping instructions announced by hosts.","staff_inclusivity":"The venue is explicitly LGBTQ+ and adult-performance oriented. Inclusion should be evaluated alongside audience scope, consent practice and physical access for the selected show.","review_signal":"Official programme evidence is stronger than generic directory ratings: decide whether you want adult revue, drag or dancing before choosing the venue.","source_urls":["https://www.stagpdx.com/","https://www.travelportland.com/culture/gay-portland/"],"research_status":"official_current_programme","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Escape Bar & Grill","city":"portland","type":"bar","description":"A Northeast Portland LGBTQ+ neighbourhood bar and grill known for karaoke, pool, drag, patio time and a less tourist-facing crowd. Its distance from downtown is part of the appeal for visitors seeking a community room where food and conversation matter as much as a dance floor.","vibe":"unpretentious queer neighbourhood bar with karaoke, pool, food and local regulars","hours":"Daily bar-and-grill operation with event-led karaoke and drag; confirm current kitchen and show hours.","link":"https://www.escapebarandgrillpdx.com/","location":"9004 NE Sandy Boulevard, Portland, OR 97220, United States","lat":45.55541,"lng":-122.57032,"intel":{"queue_wait":"Most nights are easy walk-ins; popular karaoke and drag can fill tables before they create any formal entrance line.","best_nights":"Choose a published karaoke, drag or community event for stronger energy; a weekday visit is better for food, pool and conversation with regulars.","crowd_mix":"Northeast Portland locals, queer women, gay men, trans and non-binary guests, karaoke singers and mixed-age regulars create a neighbourhood rather than tourist crowd.","dress_code":"Everyday casual clothing fits. Bring practical layers for the patio and do not expect the appearance gate of a downtown nightclub.","staff_inclusivity":"Dedicated LGBTQ+ positioning and recurring queer programming provide direct evidence; confirm mobility and seating needs with the venue before a packed show.","review_signal":"Its strongest distinction is geography and format: a food-serving neighbourhood queer bar, not a substitute for an Old Town mega-club.","source_urls":["https://www.escapebarandgrillpdx.com/","https://www.travelportland.com/culture/gay-portland/"],"research_status":"official_current_operation","updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Blue Moon","city":"rehoboth_beach","type":"restaurant","description":"A Rehoboth institution combining a refined dinner room with a separate late-night bar, drag and live entertainment programme. The experience changes after dinner service: reserve for food, then check the entertainment calendar rather than expecting every evening to operate as the same gay nightclub.","vibe":"polished dinner landmark that turns toward drag, cabaret and late queer social energy","hours":"Dinner and entertainment schedules vary seasonally; reservations and the official calendar are essential.","link":"https://bluemoonrehoboth.com/","location":"35 Baltimore Avenue, Rehoboth Beach, DE 19971, United States","lat":38.71797,"lng":-75.07923,"intel":{"queue_wait":"Dinner requires advance reservation in peak season; entertainment nights add a separate late arrival wave and limited standing room.","best_nights":"Choose a named drag, cabaret or live-entertainment night, or book dinner first for the complete Blue Moon progression.","crowd_mix":"Gay men, queer couples, long-time Rehoboth homeowners, dinner visitors, drag audiences and seasonal tourists create a notably multigenerational room.","dress_code":"Smart resort casual suits dinner, while expressive show-night clothes are welcome. No formal club code is published; beachwear should become dining-room appropriate.","staff_inclusivity":"Decades as an LGBTQ+ institution and continuous queer entertainment provide direct evidence. Older-building access and seating should be discussed during reservation.","review_signal":"Official destination coverage treats Blue Moon as both restaurant and nightlife landmark; booking the correct half of the experience prevents the most common mismatch.","source_urls":["https://www.visitrehoboth.com/things-to-do/rehoboth-beach-drag-shows","https://bluemoonrehoboth.com/"],"research_status":"official_plus_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Aqua Bar & Grill","city":"rehoboth_beach","type":"bar","description":"A Baltimore Avenue LGBTQ+ cornerstone with a broad outdoor deck, food, cocktails and a strong after-beach social rhythm. Aqua is most recognisable when the deck fills toward sunset; weather and seasonal programming determine whether it feels like relaxed dinner, tea dance or full party.","vibe":"open-air after-beach gathering with cocktails, casual food and a lively queer deck","hours":"Seasonal daily service and event-led closing; confirm weather, entertainment and kitchen times.","link":"https://aquagrillrehoboth.com/","location":"57 Baltimore Avenue, Rehoboth Beach, DE 19971, United States","lat":38.71817,"lng":-75.07863,"intel":{"queue_wait":"Peak summer weekends create a deck and bar wait after beach hours; arriving before sunset is easier than joining the late tea-dance surge.","best_nights":"Warm Friday, Saturday and holiday-weekend afternoons into evening show the full deck energy; a weekday meal is calmer and more conversational.","crowd_mix":"Gay men, mixed queer friend groups, beach visitors, homeowners and Pride tourists overlap, with the age range widening earlier in the day.","dress_code":"Resort casual, shorts and post-beach layers fit, but dry clothing and footwear are expected away from the sand. Weather protection matters on the deck.","staff_inclusivity":"The venue is explicitly part of Rehoboth's LGBTQ+ scene and official tourism identifies it as a cornerstone. Contact ahead for deck and restroom accessibility.","review_signal":"Official Rehoboth guidance consistently places Aqua at the transition from beach day to nightlife; time of arrival matters more than a blanket weekday ranking.","source_urls":["https://www.visitrehoboth.com/things-to-do/lgbtq-guide-to-rehoboth-beach","https://aquagrillrehoboth.com/"],"research_status":"official_plus_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Freddie's Beach Bar & Restaurant","city":"rehoboth_beach","type":"bar","description":"A colourful gay beach bar one block from the ocean, opened as Rehoboth's dedicated Freddie's location with food, karaoke, recurring drag, tea dance and a deliberately camp visual identity. Its daily programme is unusually dense, making the current official listing more useful than a generic weekend recommendation.","vibe":"maximalist gay beach bar with karaoke, drag, tea dance and playful all-night personality","hours":"Programme-led; recurring karaoke, Friday tea dance and weekend drag. Verify the current day on the official calendar.","link":"https://www.freddiesrb.com/","location":"3 South 1st Street, Rehoboth Beach, DE 19971, United States","lat":38.71569,"lng":-75.07822,"intel":{"queue_wait":"Dinner and early karaoke are manageable; Friday tea dance and the 21:00 drag audience can overlap, making reservations and early seating valuable.","best_nights":"Friday combines tea dance and Follies; Saturday carries another drag show, while weekday karaoke offers more participation and less destination-weekend pressure.","crowd_mix":"Gay men, drag fans, karaoke regulars, tourists, older beach veterans and first-time visitors share an intentionally extroverted room.","dress_code":"Bright resort casual and expressive looks suit the decor, but there is no published fashion gate. Arrive in dry clothes and bring tips for performers.","staff_inclusivity":"The venue explicitly calls itself a gay beach bar and publishes a sustained LGBTQ+ entertainment programme. Reservation and access needs should be raised directly.","review_signal":"Visit Rehoboth's current calendar verifies activity through autumn 2026; use those dated events rather than the site's occasionally inconsistent summary hours.","source_urls":["https://www.visitrehoboth.com/freddies-beach-bar-restaurant","https://www.freddiesrb.com/"],"research_status":"official_calendar_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Diego's Bar & Nightclub","city":"rehoboth_beach","type":"club","description":"A large LGBTQ+ dance venue beyond the boardwalk core, with indoor club space, an expansive outdoor area, DJs, drag and seasonal parties. Diego's provides the late-night scale that compact Baltimore Avenue cannot, but the Rehoboth Avenue location requires a deliberate transport plan.","vibe":"large coastal gay nightclub with outdoor space, drag and destination-weekend DJs","hours":"Seasonal and event-led; verify doors, cover, transport and closing time on the official schedule.","link":"https://diegosbarnightclub.com/","location":"37298 Rehoboth Avenue Extension, Rehoboth Beach, DE 19971, United States","lat":38.71474,"lng":-75.10054,"intel":{"queue_wait":"Summer Saturdays, Labor Day and headline DJs can produce a substantial ticket and security line; ordinary shoulder-season nights are much easier.","best_nights":"Holiday weekends and named DJs deliver the full large-club experience. A regular Friday is better when outdoor conversation matters as much as dancing.","crowd_mix":"Gay men lead, joined by drag audiences, regional weekend visitors, local queer groups and larger party crowds than the downtown bars can hold.","dress_code":"Coastal club casual works; themed parties may invite more. Bring ID, secure transport and footwear suited to both dance floor and outdoor surfaces.","staff_inclusivity":"The venue is explicitly LGBTQ+ and regularly hosts queer performers. Check event-specific age, bag, re-entry and accessibility rules before purchase.","review_signal":"Official Rehoboth drag and nightlife guides identify Diego's as a major show and dance venue; distance from the pedestrian core is the key practical caveat.","source_urls":["https://www.visitrehoboth.com/things-to-do/rehoboth-beach-drag-shows","https://diegosbarnightclub.com/"],"research_status":"official_plus_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"The Pines American Bistro","city":"rehoboth_beach","type":"restaurant","description":"A multi-level Baltimore Avenue restaurant and lounge pairing coastal dining with drag, cabaret and late entertainment. The Pines works best when guests distinguish the dining reservation from the upstairs performance or lounge plan; each has a different pace, price and sightline.","vibe":"coastal bistro polish with an upstairs queer cabaret and lounge pulse","hours":"Dinner, lounge and show schedules differ by season. Reserve and verify the exact room.","link":"https://thepinesrb.com/","location":"56 Baltimore Avenue, Rehoboth Beach, DE 19971, United States","lat":38.71815,"lng":-75.07880,"intel":{"queue_wait":"Restaurant tables and ticketed cabaret can sell separately; peak weekends reward booking both instead of assuming dinner guarantees show access.","best_nights":"Choose a named drag or cabaret production for performance, or an earlier dinner for conversation before Baltimore Avenue becomes louder.","crowd_mix":"Queer couples, dinner parties, cabaret audiences, homeowners and weekend visitors form a polished, mixed-age crowd.","dress_code":"Resort smart casual is natural without being formal. Show-night glamour fits upstairs; beachwear should be changed before a dining reservation.","staff_inclusivity":"Sustained LGBTQ+ entertainment and location inside the queer Baltimore Avenue cluster provide direct evidence. Confirm lift and seating access when booking upstairs.","review_signal":"Official guides include The Pines in Rehoboth's active drag circuit; the crucial planning detail is selecting the correct room and ticket.","source_urls":["https://www.visitrehoboth.com/things-to-do/rehoboth-beach-drag-shows","https://thepinesrb.com/"],"research_status":"official_plus_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Purple Parrot Grill","city":"rehoboth_beach","type":"restaurant","description":"A colourful Key West-style restaurant and bar near the boardwalk with a long queer following, courtyard energy, karaoke and casual food. It is a mixed venue rather than a dedicated gay bar, but its place in the town's social circuit is established and should be labelled accurately.","vibe":"tropical, mixed and loudly welcoming courtyard stop for food, karaoke and beach-town socialising","hours":"Daily seasonal restaurant and bar service; verify karaoke and entertainment times.","link":"https://ppgrill.com/","location":"134 Rehoboth Avenue, Rehoboth Beach, DE 19971, United States","lat":38.71586,"lng":-75.08074,"intel":{"queue_wait":"Dinner and wet-weather peaks create table waits; the bar is easier before the post-beach dinner wave than during summer weekend karaoke.","best_nights":"A listed karaoke or entertainment night brings the strongest queer crossover, while lunch and early dinner remain broad mixed resort service.","crowd_mix":"LGBTQ+ visitors, families, local regulars, beach tourists and karaoke groups mix freely; it should not be presented as an exclusively queer room.","dress_code":"Very casual resort clothing fits, with dry footwear and covered beachwear expected for restaurant service. No appearance gate is published.","staff_inclusivity":"Longstanding participation in Rehoboth's queer visitor economy is meaningful, but the venue is mixed. Evaluate a specific event rather than claiming exclusive community ownership.","review_signal":"Official destination material repeatedly includes Purple Parrot in the wider LGBTQ+ circuit; correct categorisation as mixed and welcoming preserves credibility.","source_urls":["https://www.visitrehoboth.com/things-to-do/lgbtq-guide-to-rehoboth-beach","https://ppgrill.com/"],"research_status":"official_destination_category_checked","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Poodle Beach","city":"rehoboth_beach","type":"other","description":"The traditional gay beach at the south end of Rehoboth's boardwalk, reached around Queen Street. It is an unstaffed public beach, not a venue: ocean conditions, lifeguard hours, sun exposure and leave-no-trace behaviour matter more than nightlife expectations.","vibe":"iconic daytime gay beach with multigenerational summer social energy by the Atlantic","hours":"Public beach access; use posted lifeguard, weather, surf and seasonal rules.","link":"https://www.visitdelaware.com/blog/post/lgbtqia-travel-guide-to-rehoboth-beach-delaware/","location":"Queen Street ocean access, Rehoboth Beach, DE 19971, United States","lat":38.70969,"lng":-75.07628,"intel":{"queue_wait":"There is no admission queue; peak summer weekends make parking, boardwalk access and the best dry-sand positions the real constraint.","best_nights":"This is a daytime beach. Late morning through lifeguarded afternoon is the relevant social window; do not treat darkness as an extension of venue hours.","crowd_mix":"Gay men are most visible, alongside queer friends, couples, long-time seasonal visitors and other public beach users; no group owns the shoreline.","dress_code":"Normal swimwear, sun protection and secure footwear for hot sand apply. Follow public-nudity rules and never photograph strangers without consent.","staff_inclusivity":"The City publicly embraces its LGBTQ+ culture, but Poodle Beach has no dedicated queer staff. Safety depends on public beach services and respectful peer behaviour.","review_signal":"State tourism identifies Poodle Beach as the official gay beach; operational advice must come from current city and beach-safety notices, not bar directories.","source_urls":["https://www.visitdelaware.com/blog/post/lgbtqia-travel-guide-to-rehoboth-beach-delaware/","https://www.rehobothbeachde.gov/experience-rehoboth-beach/pride/"],"research_status":"official_public_space_context","updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Boycott Bar","city":"phoenix","type":"bar","description":"A lesbian-owned Melrose bar operating since 2017 with DJs, drag, karaoke, Latin dance nights and women-centred events while welcoming the wider community. Its importance is not simply rarity: the programme creates different sapphic social formats rather than relying on one generic ladies' night.","vibe":"high-energy lesbian-owned bar with sapphic DJs, drag, karaoke and Latin dance nights","hours":"Event-led; verify the official social calendar for doors, cover and themed audience.","link":"https://boycottbarphx.com/","location":"4301 N 7th Avenue, Phoenix, AZ 85013, United States","lat":33.49816,"lng":-112.08265,"intel":{"queue_wait":"Ordinary early evenings are accessible; Pride, major DJs and packed sapphic parties can create a line in the compact Melrose cluster.","best_nights":"Choose karaoke, a Latin dance night, drag or a named DJ according to desired crowd. The event format matters more than simply choosing Saturday.","crowd_mix":"Lesbians and queer women are centred, with trans, non-binary and wider LGBTQ+ guests welcomed; younger dance crowds grow on major event nights.","dress_code":"Casual to expressive queer nightlife clothing fits, with no verified standing dress code. Bring ID and follow any event-specific bag guidance.","staff_inclusivity":"Lesbian ownership and a sustained women-centred programme are direct evidence. Welcoming all does not remove the need to respect the space's sapphic centre.","review_signal":"Visit Phoenix independently confirms ownership, history and programme diversity; this is stronger than an undated directory label.","source_urls":["https://www.visitphoenix.com/lgbtq/melrose-district/","https://www.visitphoenix.com/lgbtq/lgbtq-owned-businesses/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Stacy's at Melrose","city":"phoenix","type":"club","description":"A central Melrose LGBTQ+ nightlife staple with drag, dance nights, themed events and a large patio. Current official tourism highlights monthly cabaret, a second-Sunday drag show and an alternative Tuesday production, giving visitors better choices than a blanket weekend recommendation.","vibe":"ornate Melrose dance bar with varied drag, themed nights and a broad LGBTQ+ patio crowd","hours":"Event-led; verify the weekly official schedule and cover before arrival.","link":"https://www.stacysatmelrose.com/","location":"4343 N 7th Avenue, Phoenix, AZ 85013, United States","lat":33.49960,"lng":-112.08266,"intel":{"queue_wait":"Weekend and Pride queues build after the performances begin; earlier patio arrival is calmer and avoids the strongest indoor dance-floor compression.","best_nights":"Tuesday's alternative Queer Agenda, second-Sunday Lady Berries and the monthly cabaret each create different drag and audience profiles.","crowd_mix":"Gay men, drag fans, trans and non-binary guests, queer women, Melrose regulars and visitors create one of the district's broadest nightlife mixes.","dress_code":"Club-casual, drag and expressive alternative looks all fit. No verified formal code is published; heat-conscious clothing and valid ID matter.","staff_inclusivity":"Dedicated LGBTQ+ operation and programmes explicitly spanning alternative drag and community segments provide direct evidence; access needs should be confirmed.","review_signal":"The current official tourism listing provides named recurring formats, allowing the Atlas to describe real differences instead of repeating 'drag and DJs.'","source_urls":["https://www.visitphoenix.com/lgbtq/melrose-district/","https://www.visitphoenix.com/lgbtq/lgbtq-owned-businesses/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"The Rock","city":"phoenix","type":"bar","description":"A Melrose neighbourhood gay bar with karaoke, a dedicated showroom for drag and pop-ups, daily specials and a broad outdoor patio. The understated exterior and local rhythm distinguish it from Phoenix's larger dance venues; showtime, not visual scale, is the reason to choose it.","vibe":"friendly Melrose neighbourhood bar with serious karaoke, close-up drag and a roomy patio","hours":"Daily and event-led; verify karaoke, drag and food-truck nights on the current calendar.","link":"https://therockdmphoenix.com/","location":"4129 N 7th Avenue, Phoenix, AZ 85013, United States","lat":33.49505,"lng":-112.08262,"intel":{"queue_wait":"Most entry is immediate; popular drag and karaoke fill the showroom and patio rather than producing a large formal queue.","best_nights":"A named drag show or high-energy karaoke night reveals the venue's identity. Earlier patio hours suit conversation and lower sensory pressure.","crowd_mix":"Melrose locals, gay men, drag audiences, karaoke singers, Puerto Rican food-truck followers and mixed-age queer friends share the space.","dress_code":"Casual neighbourhood clothes are normal, with expressive show looks welcome. Dress for desert evenings on the patio and bring valid identification.","staff_inclusivity":"The official destination guide identifies a sustained LGBTQ+ programme rather than a temporary Pride promotion. Contact directly about showroom accessibility.","review_signal":"Visit Phoenix describes the hidden-looking exterior and unusually active showroom; visitors should not judge the bar by street presence alone.","source_urls":["https://www.visitphoenix.com/lgbtq/melrose-district/","https://www.visitphoenix.com/lgbtq/lgbtq-owned-businesses/"],"research_status":"official_destination_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Charlie's Phoenix","city":"phoenix","type":"club","description":"A Phoenix LGBTQ+ institution since 1984 that grew from a country bar into a large seven-day nightclub with multiple indoor and outdoor bars, drag, karaoke, DJs and an expansive dance floor. Western roots remain visible, but the current programme reaches far beyond two-step nights.","vibe":"large LGBTQ+ country-rooted club with drag, DJs, karaoke and a high-capacity patio","hours":"Sunday 12:00-02:00; Monday-Thursday 14:00-02:00; Friday 14:00-04:00; Saturday 12:00-04:00, subject to events.","link":"https://www.charliesphoenix.com/","location":"727 W Camelback Road, Phoenix, AZ 85013, United States","lat":33.50906,"lng":-112.08321,"intel":{"queue_wait":"Regular afternoons are easy; Pride weekend and national performers create a major line. The venue sells an official FastPass for those high-demand dates.","best_nights":"Country traditions, drag, karaoke and major DJ parties serve distinct interests. Phoenix Pride weekend is the largest version but not the easiest first visit.","crowd_mix":"Gay men, Latin and country-western dancers, drag audiences, tourists, younger club crowds and long-time Phoenix regulars fill different zones.","dress_code":"Western wear is welcome but optional. The current bag policy permits only one small searched clutch or wallet, making advance planning essential.","staff_inclusivity":"More than forty years as an LGBTQ+ venue and a large Pride programme are documented. Guests should still review current door, bag and event-specific policies.","review_signal":"The venue's official site provides exact current hours, capacity features and bag rules; those operational facts are more useful than generic popularity claims.","source_urls":["https://www.charliesphoenix.com/","https://www.visitphoenix.com/lgbtq/lgbtq-owned-businesses/"],"research_status":"official_current_policy_verified","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Kobalt Bar","city":"phoenix","type":"bar","description":"A performance-focused Phoenix LGBTQ+ bar known for curated drag, cabaret, karaoke, trivia and an active ticket calendar. Kobalt works less like an anonymous dance club and more like a stage where choosing the production determines the audience, price and pace.","vibe":"show-led LGBTQ+ bar where drag, cabaret, karaoke and trivia receive real stage focus","hours":"Event-led; use the official ticket calendar for doors, showtime, age and patio details.","link":"https://www.kobaltbarphoenix.com/","location":"3110 N Central Avenue, Suite 175, Phoenix, AZ 85013, United States","lat":33.48403,"lng":-112.07413,"intel":{"queue_wait":"Ticketed drag and Pride productions create a check-in rush; ordinary karaoke and trivia are easier if seating is not tied to a reserved ticket.","best_nights":"Choose Cabergay, a curated drag production, karaoke or trivia by name. The bar's strength is programme specificity, not one universal weekend peak.","crowd_mix":"Drag artists and fans, gay men, queer creatives, trans and non-binary audiences and cabaret regulars shift according to the production.","dress_code":"Smart casual through full drag all work unless a theme says otherwise. Bring ID, a ticket confirmation and tips for performers.","staff_inclusivity":"The sustained LGBTQ+ performance calendar and broad drag forms provide direct evidence. Contact the venue before purchase for seating or access accommodation.","review_signal":"The official live calendar confirms 2026 operation and named productions; it should override stale location or hour entries copied by older guides.","source_urls":["https://www.kobaltbarphoenix.com/","https://www.visitphoenix.com/lgbtq/lgbtq-owned-businesses/"],"research_status":"official_current_calendar","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Bar 1","city":"phoenix","type":"bar","description":"A long-running central Phoenix gay neighbourhood bar with a shaded patio, pool, darts, karaoke and community events. Bar 1 is a lower-production alternative to Melrose dance venues, suited to conversation and regulars rather than a destination spectacle every night.","vibe":"relaxed gay neighbourhood bar with patio shade, pool, darts and familiar local energy","hours":"Daily and event-led; confirm current karaoke and community-event times directly.","link":"https://www.facebook.com/Bar1Phoenix/","location":"3702 N 16th Street, Phoenix, AZ 85016, United States","lat":33.49058,"lng":-112.04743,"intel":{"queue_wait":"Entry is usually immediate; the practical constraint is finding patio seating during mild-weather weekends rather than passing a club door.","best_nights":"Karaoke and named community gatherings add movement, while a weekday evening gives the clearest version of its neighbourhood conversation.","crowd_mix":"Gay male regulars, older locals, pool and darts players, friends and visitors seeking a quieter stop form a mostly community-oriented crowd.","dress_code":"Everyday casual and desert-appropriate clothing fits. No verified fashion code; bring valid ID and a layer for cooler winter patio nights.","staff_inclusivity":"A long-running gay-bar identity provides direct evidence, but current independent programme documentation is thinner than at the Melrose venues; verify special access needs.","review_signal":"Its value is format distinction: a local patio bar outside the densest Melrose block, not another large drag-and-DJ description.","source_urls":["https://www.visitphoenix.com/lgbtq/","https://www.facebook.com/Bar1Phoenix/"],"research_status":"official_social_plus_destination_context","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Anvil","city":"phoenix","type":"bar","description":"A compact gay leather and fetish bar on East Thomas Road with themed nights and a deliberately adult, specialist atmosphere. Anvil belongs in the Atlas with clear context: it is not a generic dance option, and event rules, consent and audience expectations should be checked before arrival.","vibe":"small, adult leather-and-fetish gay bar with specialist themed nights and local regulars","hours":"Night and event-led; verify current opening, cover and theme on the official channel.","link":"https://www.facebook.com/anvilbarphoenix/","location":"2424 E Thomas Road, Phoenix, AZ 85016, United States","lat":33.48033,"lng":-112.02987,"intel":{"queue_wait":"The compact room rarely needs a famous line, but a specialist event can reach capacity quickly; early arrival helps first-time orientation.","best_nights":"Select the exact leather, gear or fetish theme rather than choosing by weekday. An ordinary social night is more approachable for newcomers.","crowd_mix":"Adult gay and bisexual men, leather community, fetish regulars and respectful curious visitors lead; some events may have narrower audience expectations.","dress_code":"Casual entry may be possible on ordinary nights, while gear events can publish specific rules. Consent, phone etiquette and respect matter more than costume performance.","staff_inclusivity":"The venue serves a defined adult gay subculture. Inclusion is real within that scope, not a claim that every event is designed for every identity.","review_signal":"Specialist category accuracy is the essential quality signal: confirm the official event and do not market Anvil as a broad all-community nightclub.","source_urls":["https://www.facebook.com/anvilbarphoenix/","https://www.visitphoenix.com/lgbtq/"],"research_status":"official_social_specialist_context","updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Hula's Bar & Lei Stand","city":"honolulu","type":"bar","description":"A Waikīkī LGBTQ+ institution on the second floor of the Waikiki Grand Hotel, shifting from daytime beach-bar views into drag, live entertainment, dancers and late-night DJs. Its long hours and location near Queen's Surf make it the clearest bridge between beach day and queer nightlife.","vibe":"open-air Waikīkī institution moving from beach views and food into drag and late dancing","hours":"Open daily 11:00-02:00 according to the current official contact page.","link":"https://hulas.com/","location":"134 Kapahulu Avenue, 2nd Floor, Honolulu, HI 96815, United States","lat":21.27228,"lng":-157.82193,"intel":{"queue_wait":"Daytime entry is easy; Pride afterparties, major drag and late Friday-Saturday programmes can create a stair and ticket bottleneck.","best_nights":"Afternoon gives the view and social lounge, while named drag and weekend DJ nights reveal the club version. Honolulu Pride afterparty is the highest-demand date.","crowd_mix":"Local gay men, international visitors, drag audiences, beachgoers, mixed queer groups and long-time regulars create a visitor-heavy but genuinely rooted crowd.","dress_code":"Resort casual works by day and expressive clubwear by night. Wear dry clothes away from the beach, bring ID and check Pride bag rules.","staff_inclusivity":"Decades of LGBTQ+ operation and official Pride partnership provide direct evidence. The second-floor location makes lift and mobility confirmation important.","review_signal":"Official hours and Pride programming verify current operation; Go Hawaiʻi also distinguishes Hula's as both lounge and nightclub rather than a single-format bar.","source_urls":["https://hulas.com/contact/","https://www.gohawaii.com/experiences/lgbtq/lgbtq-nightlife","https://www.honolulupride.com/"],"research_status":"official_current_operation","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Bacchus Waikiki","city":"honolulu","type":"bar","description":"A compact upstairs gay bar on Lewers Street with nightly DJs, strong cocktails and a more conversational scale than Honolulu's largest clubs. Its current owner came through the bar's own staff, reinforcing a local continuity that matters in a visitor-heavy neighbourhood.","vibe":"compact upstairs gay cocktail bar with nightly DJs and an easy Waikīkī social rhythm","hours":"Nightly operation; verify the current official schedule and special-event opening.","link":"https://bacchus2.com/","location":"408 Lewers Street, Honolulu, HI 96815, United States","lat":21.28020,"lng":-157.83119,"intel":{"queue_wait":"The upstairs room is usually an easy stop, but its small scale means Pride and holiday nights can feel full before a visible street queue forms.","best_nights":"Nightly DJs provide consistency; arrive earlier for conversation or later for a denser bar rather than expecting a separate giant dance floor.","crowd_mix":"Gay men, Waikīkī visitors, local regulars, couples and small friend groups dominate a more intimate room than Scarlet or Hula's.","dress_code":"Resort casual and simple night-out clothes fit. Bring ID and use practical footwear for the upstairs location.","staff_inclusivity":"A dedicated gay-bar identity, current ownership history and official tourism inclusion provide direct evidence. Ask directly about stair and mobility access.","review_signal":"The official site confirms active nightly DJ operation and current ownership; its value is intimacy and cocktails, not pretending to be Honolulu's biggest club.","source_urls":["https://bacchus2.com/","https://www.gohawaii.com/experiences/lgbtq/lgbtq-nightlife"],"research_status":"official_current_operation","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Scarlet Honolulu","city":"honolulu","type":"club","description":"Honolulu's largest dedicated LGBTQ+ nightclub, occupying a downtown Chinatown space with drag, dancers, large themed productions and weekend DJs. It is also the official opening-party venue for Honolulu Pride 2026, confirming both current operation and its role in the island's biggest queer celebration.","vibe":"large downtown LGBTQ+ club with theatrical drag, dancers and high-production weekend parties","hours":"Friday-Saturday approximately 20:00-02:00; special events vary. Verify tickets and doors.","link":"https://www.scarlethonolulu.com/","location":"80 S Pauahi Street, Honolulu, HI 96813, United States","lat":21.31178,"lng":-157.86273,"intel":{"queue_wait":"Weekend headliners and the official Pride opening party create the longest lines; ticket holders should arrive before the main performance window.","best_nights":"Friday and Saturday are the full production nights. The 16 October 2026 Pride opening party is the peak version, with much higher demand.","crowd_mix":"Gay men, queer women, trans and non-binary guests, drag audiences, visitors, local club crowds and Pride tourists mix in a broad but nightlife-focused room.","dress_code":"Expressive clubwear, drag and resort night-out looks fit. Check current bag, ticket and re-entry rules and bring government-issued ID.","staff_inclusivity":"Dedicated LGBTQ+ operation and official Honolulu Pride partnership are direct evidence. Large-event accessibility and sensory needs should be confirmed before purchase.","review_signal":"Go Hawaiʻi and Honolulu Pride both identify Scarlet as a current major LGBTQ+ club; official 2026 event use resolves stale nightlife directories.","source_urls":["https://www.gohawaii.com/experiences/lgbtq/lgbtq-nightlife","https://www.honolulupride.com/"],"research_status":"official_pride_partner_current","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Wang Chung's Karaoke Bar","city":"honolulu","type":"bar","description":"An LGBTQIA+-centred open-mic karaoke bar inside the Stay Hotel, operating nightly with an extensive song catalogue, private Red Room and recurring sapphic programming. It is more participatory than performative: the room's energy comes from strangers singing together rather than watching a distant stage.","vibe":"friendly Waikīkī queer karaoke where locals and visitors share the mic every night","hours":"Daily 19:00-02:00 according to the current official site.","link":"https://www.wangchungs.com/","location":"2424 Koa Avenue, inside Stay Hotel, Honolulu, HI 96815, United States","lat":21.27628,"lng":-157.82370,"intel":{"queue_wait":"Ordinary entry is easy, but seats and song rotation tighten on Sapphic Saturday, Pride and private-room nights; book the Red Room separately.","best_nights":"Sapphic Saturday centres queer women, while any regular night works for open-mic participation. Arrive earlier if singing more than once matters.","crowd_mix":"LGBTQIA+ locals, Waikīkī visitors, queer women on named nights, karaoke enthusiasts and celebration groups create a highly interactive mix.","dress_code":"Casual resort and karaoke-night clothes work. No fashion code is published; the venue is 21+ and government ID is essential.","staff_inclusivity":"The official site explicitly says it serves the LGBTQIA+ community and publishes a sapphic safe-space programme, providing direct evidence beyond friendly branding.","review_signal":"Exact current hours, address and community language are published by the venue; its karaoke participation and private-room option distinguish it from the dance clubs.","source_urls":["https://www.wangchungs.com/","https://www.gohawaii.com/experiences/lgbtq/lgbtq-nightlife"],"research_status":"official_current_operation","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Queen's Surf Beach","city":"honolulu","type":"other","description":"The Waikīkī beach area beside Kapiʻolani Park long associated with Honolulu's LGBTQ+ community and within easy reach of Hula's. It remains a public, unstaffed-by-community shoreline rather than a gay venue; ocean warnings, lifeguards, sun and respect for every beach user set the rules.","vibe":"visible queer-friendly Waikīkī beach stretch with easy daytime social energy near Kapiʻolani Park","hours":"Public beach access; follow posted ocean, park, lifeguard and nighttime rules.","link":"https://www.gohawaii.com/islands/oahu/regions/honolulu/waikiki","location":"Queen's Surf Beach, 2700 Kalākaua Avenue, Honolulu, HI 96815, United States","lat":21.27162,"lng":-157.82139,"intel":{"queue_wait":"No entry line exists; weekends and Pride make nearby parking, shade and safe belongings storage the real constraints.","best_nights":"Use the beach in daylight and lifeguarded conditions. Sunset is social, but darkness is not an extension of staffed venue hours.","crowd_mix":"LGBTQ+ locals and visitors, surfers, swimmers, families and general Waikīkī beach users share a public shore with no exclusive ownership.","dress_code":"Normal lawful swimwear, reef-aware sun protection and water shoes as needed. Never photograph people without consent and secure valuables before swimming.","staff_inclusivity":"Community visibility is longstanding, but there is no dedicated queer staff or door policy. Public safety services and respectful peer behaviour define inclusion.","review_signal":"The strongest evidence is geographic and cultural context, not a fabricated service rating. Daily ocean conditions should override any evergreen recommendation.","source_urls":["https://www.gohawaii.com/experiences/lgbtq/lgbtq-nightlife","https://www.gohawaii.com/islands/oahu/regions/honolulu/waikiki"],"research_status":"official_public_space_context","updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"The Surfjack Hotel & Swim Club","city":"honolulu","type":"hotel","description":"A design-forward Waikīkī hotel with a documented relationship to Honolulu's queer cultural calendar and a central Lewers Street location near Bacchus and the wider nightlife circuit. It is a mainstream hotel rather than an LGBTQ-only property; the value is visible partnership, walkability and a locally oriented public programme.","vibe":"design-led Waikīkī stay with poolside culture and practical access to queer nightlife","hours":"Hotel reception and guest operations are continuous; pool, restaurant and public-event hours vary.","link":"https://surfjack.com/","location":"412 Lewers Street, Honolulu, HI 96815, United States","lat":21.28029,"lng":-157.83123,"intel":{"queue_wait":"Check-in follows standard hotel peaks; Pride and pool events can produce separate wristband, guest-list and lift traffic.","best_nights":"Stay for walkability and design throughout the week; a verified Pride or cultural pool event adds community relevance without making every night queer programming.","crowd_mix":"Design travellers, couples, international visitors, local event guests and LGBTQ+ Pride travellers mix in a mainstream boutique-hotel environment.","dress_code":"Resort casual applies, with swimwear confined to pool areas and event rules controlling special parties. No queer-specific appearance code exists.","staff_inclusivity":"Documented Pride participation is meaningful but does not equal exclusive certification. Confirm chosen-name, room-sharing and accessibility needs directly before arrival.","review_signal":"The recommendation rests on location, current hotel operation and public community partnership—not on importing room-star scores into an inclusion claim.","source_urls":["https://surfjack.com/","https://www.honolulupride.com/"],"research_status":"official_hotel_plus_community_partnership","updated_at":"2026-08-27T00:00:00Z"}}
]
$qa_us_places$) p(name text,city text,type text,description text,vibe text,hours text,link text,location text,lat double precision,lng double precision,intel jsonb)
), upd as (
  update public.places p set type=s.type,description=s.description,vibe=s.vibe,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,
    venue_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
  from src s where lower(trim(p.city))=s.city and lower(trim(p.name))=lower(trim(s.name)) returning p.id
)
insert into public.places(name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,venue_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,description,vibe,array[]::text[],hours,link,location,lat,lng,intel,true,'approved',timezone('utc',now()) from src s
where not exists(select 1 from public.places p where lower(trim(p.city))=s.city and lower(trim(p.name))=lower(trim(s.name)));

-- Events: dated from current organiser pages. Past 2026 flagship dates remain as
-- annual reference records; future events are never assigned an invented date.
with src as (
  select * from jsonb_to_recordset($qa_us_events$
[
  {"name":"Families with Pride Houston 2026","city":"houston","description":"The fifth annual family-centred LGBTQIA+ History Month gathering brings children, parents, caregivers and allies to Discovery Green for a free morning of community organisations and celebration. Harris County and the Greater Houston LGBTQ+ Chamber publicly confirm the 24 October date.","link":"https://cao.harriscountytx.gov/Connect/Newsroom/abbie-kamin-families-with-pride-2026-returns","date":"2026-10-24","start_date":"2026-10-24","end_date":"2026-10-24","location":"Discovery Green, 1500 McKinney Street, Houston, TX 77010, United States","lat":29.75322,"lng":-95.35986,"vibe":"affirming daytime Pride built for LGBTQ+ families, children and allies","intel":{"entry_wait":"Free public event; the 10:00 opening can concentrate registration and activity lines, but there is no nightclub-style door.","best_arrival":"Arrive around 09:45 for the full 10:00-13:00 programme and easier downtown transport before midday activity peaks.","crowd_mix":"LGBTQ+ parents, children, caregivers, community organisations, allies and public officials create an all-ages family audience.","dress_code":"Weather-ready park clothing, sun protection and comfortable shoes; family Pride expression is welcome without a formal code.","host_inclusivity":"The event is explicitly designed for LGBTQIA+ children and families and is co-produced with public and LGBTQ+ chamber partners.","source_urls":["https://cao.harriscountytx.gov/Connect/Newsroom/abbie-kamin-families-with-pride-2026-returns","https://business.houstonlgbtchamber.com/eventcalendar/Details/join-us-at-families-with-pride-1899926"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Beyond the Binary Crafting Night – September 2026","city":"houston","description":"A safer-space arts and conversation evening at the Montrose Center for non-binary, gender-nonconforming, trans and other non-cisgender adults. The group invites participants to bring a current craft or start something new while building community without a nightlife threshold.","link":"https://montrosecenter.org/event/beyond-the-binary-crafting-night-114/2026-09-24/","date":"2026-09-24","start_date":"2026-09-24","end_date":"2026-09-24","location":"The Montrose Center, 401 Branard Street, Houston, TX 77006, United States","lat":29.73642,"lng":-95.38644,"vibe":"gentle trans and non-binary community connection through crafts and conversation","intel":{"entry_wait":"No public party queue; capacity and safer-space participation rules matter, so check the organiser page before attending.","best_arrival":"Arrive before the 18:30 start with enough time to find Room 114 and settle without interrupting the facilitated group.","crowd_mix":"Non-binary, gender-nonconforming, trans and non-cisgender adults are specifically centred; this is not a general spectator event.","dress_code":"Comfortable everyday clothing suitable for seated crafting; bring a project if desired and respect privacy around photographs.","host_inclusivity":"The Montrose Center defines the group by lived identity, safer-space discussion and community support, with an 18+ participation rule.","source_urls":["https://montrosecenter.org/event/beyond-the-binary-crafting-night-114/2026-09-24/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Houston Pride Celebration 2026","city":"houston","description":"Houston's large annual LGBTQ+ parade and festival returned in August 2026 after a schedule change from the earlier June plan. The record preserves the confirmed 2026 edition as an annual anchor without inventing a 2027 date; travellers must use the organiser for the next edition.","link":"https://pridehouston365.org/celebration/","date":"2026-08-15","start_date":"2026-08-15","end_date":"2026-08-15","location":"Downtown Houston, Houston, TX, United States","lat":29.76025,"lng":-95.36955,"vibe":"large civic Pride combining visibility, protest, festival energy and a night parade","intel":{"entry_wait":"The parade is public while festival gates and security create separate waits; downtown heat and road closures add more friction than ticket scanning alone.","best_arrival":"Use the final organiser schedule, transit map and heat plan; the 2026 event moved dates, proving old saved listings are unsafe planning tools.","crowd_mix":"LGBTQ+ Houstonians, families, activists, performers, community groups, visitors and allies form one of the city's broadest queer gatherings.","dress_code":"Heat-safe Pride clothing, water and comfortable walking shoes are essential; expressive looks remain secondary to weather preparation.","host_inclusivity":"Pride Houston 365 is a volunteer-run LGBTQIA+ organisation with a public parade-and-festival mission dating to 1976.","source_urls":["https://pridehouston.org/celebration/","https://www.visithoustontexas.com/lgbtq/post/pride-month-in-houston/"],"updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Portland Pride Waterfront Festival & Parade 2026","city":"portland","description":"Portland's official Pride weekend brought the community to Tom McCall Waterfront Park on 18–19 July 2026 with a family-friendly festival, parade, organisations and performance. The dated record is retained as the annual flagship; no future edition is assigned until Pride Northwest publishes it.","link":"https://portlandpride.org/2026-portland-pride-official-events","date":"2026-07-18","start_date":"2026-07-18","end_date":"2026-07-19","location":"Tom McCall Waterfront Park, Portland, OR, United States","lat":45.51644,"lng":-122.67064,"vibe":"large public Pride weekend mixing community resources, performance and a downtown parade","intel":{"entry_wait":"Waterfront security and peak parade movement create queues even when outdoor areas are open; bridge, transit and road closures alter access.","best_arrival":"Follow Pride Northwest's final accessibility and route map, arriving before the headline or parade wave rather than relying on generic park directions.","crowd_mix":"Families, trans and non-binary community, queer organisations, performers, activists, tourists and allies gather across the weekend.","dress_code":"Weather layers, sun protection, water and practical shoes suit a long waterfront day; expressive Pride clothing is welcome.","host_inclusivity":"The official programme includes community, arts and family formats rather than defining Pride only through nightlife.","source_urls":["https://portlandpride.org/2026-portland-pride-official-events","https://www.travelportland.com/culture/gay-portland/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"QTM Support – September 2026","city":"portland","description":"Q Center's recurring Queer & Trans Masc support programme offers a facilitated community setting rather than a public entertainment event. The 1 September listing is useful to residents and longer-stay visitors seeking identity-specific connection; registration and privacy expectations should be respected.","link":"https://www.pdxqcenter.org/","date":"2026-09-01","start_date":"2026-09-01","end_date":"2026-09-01","location":"Q Center, 4115 N Mississippi Avenue, Portland, OR 97217, United States","lat":45.55328,"lng":-122.67559,"vibe":"identity-specific queer and trans masculine peer connection in a community-centre setting","intel":{"entry_wait":"Registration replaces a door queue; confirm eligibility and whether the session is in person before travelling.","best_arrival":"Arrive before the published start so group agreements and introductions are not missed.","crowd_mix":"Queer and trans masculine participants are centred; this is a support space, not an open social for observers.","dress_code":"Comfortable everyday clothes with no appearance expectation. Privacy and chosen names matter more than presentation.","host_inclusivity":"Q Center is Portland's LGBTQIA2S+ community centre and publishes the group as part of its direct support programme.","source_urls":["https://www.pdxqcenter.org/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Sereni-Tea Queer-Led Tea Meditation – September 2026","city":"portland","description":"A queer-led tea meditation at Q Center on 2 September creates a slow, sober community format distinct from Portland's nightlife calendar. The repeated programme combines guided attention, tea and connection in the city's principal LGBTQIA2S+ community centre.","link":"https://www.pdxqcenter.org/","date":"2026-09-02","start_date":"2026-09-02","end_date":"2026-09-02","location":"Q Center, 4115 N Mississippi Avenue, Portland, OR 97217, United States","lat":45.55328,"lng":-122.67559,"vibe":"quiet sober queer gathering built around tea, meditation and low-pressure connection","intel":{"entry_wait":"Advance registration may control capacity; there is no nightlife queue, but late entry can disrupt the meditation format.","best_arrival":"Reach Q Center early enough to settle, disclose access needs and begin with the group.","crowd_mix":"Queer adults seeking sober connection, mindfulness and a lower-sensory social environment form the likely audience.","dress_code":"Soft comfortable clothing suitable for stillness; ask about seating adaptations instead of assuming floor-based practice.","host_inclusivity":"The programme is queer-led and hosted inside Q Center, providing direct community ownership and an affirming setting.","source_urls":["https://www.pdxqcenter.org/"],"updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"SUNFESTIVAL 2026","city":"rehoboth_beach","description":"CAMP Rehoboth's Labor Day benefit closes summer with David Archuleta and a live auction on 5 September, followed by a large dance night with DJs Robbie Leslie and James Anthony on 6 September. Proceeds directly support CAMP's year-round community work.","link":"https://give.camprehoboth.org/member-advance-tickets-sf-2026","date":"2026-09-05","start_date":"2026-09-05","end_date":"2026-09-06","location":"Rehoboth Beach Convention Center, 229 Rehoboth Avenue, Rehoboth Beach, DE 19971, United States","lat":38.71632,"lng":-75.08300,"vibe":"destination Labor Day fundraiser moving from live performance into a classic gay dance night","intel":{"entry_wait":"Both nights are ticketed and the fundraiser commonly sells out; doors at 18:30 Saturday and 19:00 Sunday create concentrated arrivals.","best_arrival":"Use separate ticket and door details for the concert-auction and dance night; they are not interchangeable sessions.","crowd_mix":"CAMP supporters, gay men, queer residents, regional visitors, donors, music audiences and long-time Rehoboth regulars gather across two formats.","dress_code":"Polished resort evening clothing suits Saturday; dance-ready expressive looks fit Sunday. No compulsory formal code is published.","host_inclusivity":"All proceeds benefit CAMP Rehoboth, connecting the destination party directly to year-round LGBTQ+ programmes and safer-community work.","source_urls":["https://give.camprehoboth.org/member-advance-tickets-sf-2026","https://give.camprehoboth.org/sunfestival-2026-live-auction"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"CAMP Rehoboth Block Party 2026","city":"rehoboth_beach","description":"Baltimore Avenue becomes a public celebration of Southern Delaware's inclusive community on 18 October, with vendors, organisations and local businesses supporting CAMP Rehoboth. The event runs rain or shine from 11:00 to 16:00 and publishes a direct accessibility contact.","link":"https://give.camprehoboth.org/events/block-party","date":"2026-10-18","start_date":"2026-10-18","end_date":"2026-10-18","location":"Second block of Baltimore Avenue, Rehoboth Beach, DE 19971, United States","lat":38.71818,"lng":-75.07883,"vibe":"open-air community street fair joining queer organisations, local makers and coastal neighbours","intel":{"entry_wait":"No ticket queue for general visitors; the compact street becomes busy around midday and parking is the larger obstacle.","best_arrival":"Arrive near 11:00 for easier circulation and the full vendor period before the 16:00 close.","crowd_mix":"LGBTQ+ residents, families, visitors, local businesses, nonprofits, makers and allies form a broad public crowd.","dress_code":"Weather-ready street-fair layers and comfortable shoes; the event runs rain or shine unless severe weather intervenes.","host_inclusivity":"CAMP publishes both its all-orientations-and-identities mission and an accessibility contact with an October 2 accommodation deadline.","source_urls":["https://give.camprehoboth.org/events/block-party"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Freddie's Follies – Labor Day Friday 2026","city":"rehoboth_beach","description":"Freddie's recurring Friday drag production brings a close-up show to its colourful beach-bar room on 4 September from 21:00 to 23:00, followed by late karaoke. It offers a smaller, more participatory counterpoint to the convention-centre SUNFESTIVAL weekend.","link":"https://www.visitrehoboth.com/freddies-beach-bar-restaurant","date":"2026-09-04","start_date":"2026-09-04","end_date":"2026-09-04","location":"Freddie's Beach Bar & Restaurant, 3 South 1st Street, Rehoboth Beach, DE 19971, United States","lat":38.71569,"lng":-75.07822,"vibe":"close-up beach-bar drag leading into karaoke on a busy holiday weekend","intel":{"entry_wait":"Reservations are wise because dinner, tea-dance traffic and the 21:00 drag audience can overlap in the compact room.","best_arrival":"Arrive before 20:30 for seating and service before the show; stay after 23:00 only if late karaoke suits the night.","crowd_mix":"Drag fans, gay beach visitors, Freddie's regulars, performers and Labor Day tourists create an animated mixed-age audience.","dress_code":"Festive resort-night clothing works, with tips for performers and valid ID more important than formal glamour.","host_inclusivity":"Freddie's identifies itself as a gay beach bar and programs recurring queer performers rather than a one-off Pride show.","source_urls":["https://www.visitrehoboth.com/freddies-beach-bar-restaurant"],"updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Phoenix Pride Festival & Parade 2026","city":"phoenix","description":"Phoenix Pride's autumn festival and parade takes place 10–11 October 2026, when desert temperatures are more workable than June. The event remains scheduled while the organisation restructures financially, so visitors should follow the official channel for any operational update.","link":"https://phoenixpride.org/","date":"2026-10-10","start_date":"2026-10-10","end_date":"2026-10-11","location":"Steele Indian School Park, 300 E Indian School Road, Phoenix, AZ 85012, United States","lat":33.49524,"lng":-112.06967,"vibe":"large autumn Pride weekend balancing community visibility, performance and desert-city celebration","intel":{"entry_wait":"Festival ticketing, security and transit create the main wait; organisational restructuring makes final official updates especially important.","best_arrival":"Follow the published gate and parade schedule and enter before the hottest or headline period rather than improvising at midday.","crowd_mix":"LGBTQ+ Arizonans, families, performers, community organisations, tourists and allies gather across the park and parade.","dress_code":"Heat-aware Pride clothing, water, sunscreen and practical shoes remain essential even in October.","host_inclusivity":"Phoenix Pride is the established LGBTQ+ organiser and the festival is explicitly built for community members and allies; current financial status should be transparently monitored.","source_urls":["https://www.visitphoenix.com/events/annual-events/","https://phoenixpride.org/about/faq/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Charlie's Phoenix Pride Weekend 2026","city":"phoenix","description":"Charlie's expands its indoor and outdoor operation for four Pride nights from 8–11 October with national drag talent, DJs, food, vendors and extra patio bars. This is a private 21+ club programme, distinct from the public festival and parade at Steele Indian School Park.","link":"https://www.charliesphoenix.com/","date":"2026-10-08","start_date":"2026-10-08","end_date":"2026-10-11","location":"Charlie's Phoenix, 727 W Camelback Road, Phoenix, AZ 85013, United States","lat":33.50906,"lng":-112.08321,"vibe":"four-night high-capacity Pride club takeover with drag headliners, DJs and outdoor expansion","intel":{"entry_wait":"This is Charlie's highest-demand weekend; advance FastPass and early arrival can materially reduce a long 21+ security line.","best_arrival":"Choose the specific performer and day, then arrive before the headline rush rather than treating all four nights as interchangeable.","crowd_mix":"Gay club crowds, drag fans, Pride tourists, Latin and country regulars and national-performer audiences fill several venue zones.","dress_code":"Pride clubwear and expressive looks fit, but the strict small-clutch bag policy and valid ID are non-negotiable.","host_inclusivity":"The venue has served Phoenix's LGBTQ+ community since 1984 and publishes a large Pride programme; private-club policies still apply.","source_urls":["https://www.charliesphoenix.com/","https://charliesfastpass.com/"],"updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Honolulu Pride Parade 2026","city":"honolulu","description":"The 17 October parade travels through Waikīkī from Magic Island toward the Waikīkī Shell, centring LGBTQIA+ and MVPFAFF+ organisations, businesses and community groups. It is the public processional heart of Hawaiʻi's October Pride season.","link":"https://www.honolulupride.com/","date":"2026-10-17","start_date":"2026-10-17","end_date":"2026-10-17","location":"Kalākaua Avenue, from Magic Island to Waikīkī Shell, Honolulu, HI, United States","lat":21.28544,"lng":-157.83805,"vibe":"public Waikīkī procession celebrating queer resilience, local culture and island-wide visibility","intel":{"entry_wait":"No spectator ticket queue, but road closures, viewing areas and parade staging make transport and shade the real constraints.","best_arrival":"Use the final official route and time, reaching a chosen viewing point early with water and sun protection.","crowd_mix":"Local LGBTQIA+ and MVPFAFF+ groups, Native Hawaiian and Pacific communities, families, visitors, businesses and allies join the route.","dress_code":"Tropical-weather Pride clothing, sunscreen and walking shoes; cultural symbols should be worn with understanding rather than as costume.","host_inclusivity":"Hawaiʻi LGBT Legacy Foundation explicitly centres queer resilience and uses locally relevant LGBTQIA+/MVPFAFF+ language in the 2026 programme.","source_urls":["https://www.honolulupride.com/","https://humanservices.hawaii.gov/lgbtq-commission/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Honolulu Pride Festival 2026","city":"honolulu","description":"After the parade, Tom Moffatt Waikīkī Shell hosts four hours of live entertainment and more than seventy community booths on 17 October. The festival is a separate destination from the route and has its own ticket, entry and VIP conditions.","link":"https://www.honolulupride.com/","date":"2026-10-17","start_date":"2026-10-17","end_date":"2026-10-17","location":"Tom Moffatt Waikīkī Shell, 2805 Monsarrat Avenue, Honolulu, HI 96815, United States","lat":21.26877,"lng":-157.81806,"vibe":"large open-air Pride festival joining island community resources with live entertainment","intel":{"entry_wait":"Festival gates, security and VIP wristbands create a separate queue from parade viewing; do not assume route participation grants venue entry.","best_arrival":"Allow enough time after the parade to reach the Shell before the evening entertainment begins and review prohibited-item rules.","crowd_mix":"Community organisations, performers, families, local queer residents, visitors and Pride sponsors meet across more than seventy booths.","dress_code":"Outdoor festival clothing, water and weather protection; evening can feel cooler after a hot parade day.","host_inclusivity":"The official programme combines entertainment with a substantial community-resource presence, keeping service organisations visible within celebration.","source_urls":["https://www.honolulupride.com/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Honolulu Pride Opening Party 2026","city":"honolulu","description":"Scarlet Honolulu hosts the official Pride opening party on Friday 16 October from 22:00 to 02:00. It is a ticketed adult nightclub event within the wider Pride programme, not the correct recommendation for families seeking the following day's parade and festival.","link":"https://www.honolulupride.com/","date":"2026-10-16","start_date":"2026-10-16","end_date":"2026-10-17","location":"Scarlet Honolulu, 80 S Pauahi Street, Honolulu, HI 96813, United States","lat":21.31178,"lng":-157.86273,"vibe":"official late-night Pride launch with drag, DJs and downtown club production","intel":{"entry_wait":"VIP access and general ticketing use separate lines; arrive before 22:00 if headline sightlines and a smoother security check matter.","best_arrival":"Plan transport between Waikīkī and Chinatown before drinking and do not confuse the 02:00 end with daytime Pride timings.","crowd_mix":"Adult Pride visitors, local club crowds, drag fans, queer residents and sponsor guests create a dense nightlife audience.","dress_code":"Expressive Pride clubwear fits; check Scarlet's bag rules, bring valid ID and use secure pockets.","host_inclusivity":"The party is officially produced within Honolulu Pride at an established LGBTQ+ club, with Pride's wider local-language mission behind it.","source_urls":["https://www.honolulupride.com/","https://www.gohawaii.com/experiences/lgbtq/lgbtq-nightlife"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Honolulu Pride After Party 2026","city":"honolulu","description":"Hula's Bar & Lei Stand hosts the official afterparty on 17 October from 21:00 to 02:00, carrying the parade-and-festival day back into a longstanding Waikīkī LGBTQ+ venue. VIP access is part of the wider Pride package; general admission details require the official listing.","link":"https://www.honolulupride.com/","date":"2026-10-17","start_date":"2026-10-17","end_date":"2026-10-18","location":"Hula's Bar & Lei Stand, 134 Kapahulu Avenue, Honolulu, HI 96815, United States","lat":21.27228,"lng":-157.82193,"vibe":"official Waikīkī Pride afterparty blending a local institution with festival-night release","intel":{"entry_wait":"Expect one of Hula's longest annual queues, with VIP and general entry operating differently; capacity and the upstairs route matter.","best_arrival":"Allow recovery time after the festival but reach Hula's before the 21:00 surge if entry certainty matters.","crowd_mix":"Pride performers, visitors, local gay regulars, queer groups and festival attendees fill a more tourist-heavy room than an ordinary Hula's night.","dress_code":"Festival-to-club clothing works if dry and secure; bring ID and review any Pride bag restriction.","host_inclusivity":"An official Honolulu Pride partnership at a decades-old LGBTQ+ venue supplies direct institutional evidence, while access remains adult nightlife-specific.","source_urls":["https://www.honolulupride.com/","https://hulas.com/contact/"],"updated_at":"2026-08-27T00:00:00Z"}}
]
$qa_us_events$) e(name text,city text,description text,link text,date date,start_date date,end_date date,location text,lat double precision,lng double precision,vibe text,intel jsonb)
), upd as (
  update public.events e set description=s.description,link=s.link,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,lat=s.lat,lng=s.lng,
    vibe=s.vibe,event_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
  from src s where lower(trim(e.city))=s.city and lower(trim(e.name))=lower(trim(s.name)) returning e.id
)
insert into public.events(name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from src s
where not exists(select 1 from public.events e where lower(trim(e.city))=s.city and lower(trim(e.name))=lower(trim(s.name)));

with src as (
  select * from jsonb_to_recordset($qa_us_services$
[
  {"name":"The Montrose Center","city":"houston","type":"wellness","provider_name":"The Montrose Center","contact":"713-529-0037; 24-hour LGBT Switchboard and survivor helpline 713-529-3211","booking_link":"https://montrosecenter.org/services/","description":"Houston's full-service LGBTQ+ community centre provides mental and behavioural health care, survivor support, youth and senior programmes, housing work, groups and a home for dozens of community organisations. Community rooms operate beyond weekday business hours according to the live calendar.","hours":"Business office Monday-Thursday 08:00-18:15; Friday 08:00-17:00. Community centre opens for scheduled programmes seven days.","link":"https://montrosecenter.org/","location":"401 Branard Street, Houston, TX 77006, United States","lat":29.73642,"lng":-95.38644,"price_tier":"$","vibe":"deep, practical LGBTQ+ care connecting crisis support with everyday community life","source":"Montrose Center official services, contact and calendar; checked 2026-08-27","intel":{"booking_lead_time":"Clinical, housing, youth and group services use different intake routes; call the main line or the specific programme before arrival.","best_time":"Weekday business hours suit intake, while scheduled evening groups use community-centre access; urgent survivor support uses the 24-hour helpline.","client_mix":"LGBTQ+ youth, adults, seniors, survivors, families, trans people, people seeking therapy and community organisations across Greater Houston.","preparation":"State the service, urgency, insurance or cost question, language and access need; do not assume every programme accepts walk-ins.","provider_inclusivity":"The organisation has served Houston's LGBTQ+ community since 1978 and combines licensed clinicians with peer and community programmes.","source_urls":["https://montrosecenter.org/","https://montrosecenter.org/services/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Legacy Community Health – Montrose","city":"houston","type":"wellness","provider_name":"Legacy Community Health","contact":"832-548-5000","booking_link":"https://www.legacycommunityhealth.org/patient-center/locations/montrose/","description":"A major community-health clinic with roots in Houston's HIV response, offering primary care, HIV prevention and treatment, sexual health, behavioural health and other services in Montrose. It is a healthcare provider, not a community drop-in, so appointments and eligibility should be confirmed.","hours":"Clinic hours vary by department; use the current Montrose location page and appointment line.","link":"https://www.legacycommunityhealth.org/","location":"1415 California Street, Houston, TX 77006, United States","lat":29.74232,"lng":-95.39552,"price_tier":"$","vibe":"established community healthcare with deep HIV expertise and broad affirming clinical access","source":"Legacy Community Health official Montrose and service pages; checked 2026-08-27","intel":{"booking_lead_time":"Primary care, behavioural health and HIV services have separate availability; book ahead and ask about urgent sexual-health options.","best_time":"Call during weekday clinic hours with exposure or medication timing stated clearly so the correct department can route care.","client_mix":"LGBTQ+ patients, people living with or preventing HIV, uninsured and insured patients, families and the wider Houston community.","preparation":"Bring identification, medication list and insurance information if available; ask about sliding-fee requirements and confidentiality before arrival.","provider_inclusivity":"Legacy grew from community HIV care and publicly maintains LGBTQ+ and sexual-health services; competency is programme-based rather than a decorative badge.","source_urls":["https://www.legacycommunityhealth.org/patient-center/locations/montrose/","https://www.legacycommunityhealth.org/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Grace Place / Asia's House","city":"houston","type":"other","provider_name":"Grace Place with The Montrose Center","contact":"Use the official Grace Place or Montrose Center referral route","booking_link":"https://www.graceplacehouston.org/","description":"Grace Place supports young people experiencing homelessness and opens Asia's House in September 2026 as Houston's first LGBTQ+-affirming emergency shelter specifically for ages 15–17. The residence address is protected; the Atlas must never convert a public news description into a precise shelter pin.","hours":"Referral and shelter access are programme-based; contact the provider rather than visiting an assumed address.","link":"https://www.graceplacehouston.org/","location":"Houston referral area; emergency shelter address protected","lat":29.76040,"lng":-95.36980,"price_tier":"$","vibe":"identity-affirming emergency shelter and practical care for queer teenagers in crisis","source":"Grace Place, Montrose Center and current Houston reporting; checked 2026-08-27","intel":{"booking_lead_time":"Emergency access should use the current provider or youth-crisis referral process; do not travel to a guessed address.","best_time":"Seek help as soon as housing becomes unsafe. Immediate danger belongs with emergency services or the provider's stated crisis route.","client_mix":"Young people aged 15–17 of all sexualities and genders, with explicit affirmation for LGBTQ+ and trans youth experiencing homelessness.","preparation":"Share age, immediate safety, medical needs and safe-contact method; protect location and personal information from public posting.","provider_inclusivity":"The shelter is explicitly designed as LGBTQ+-affirming and named for trans Houston advocate Asia Jynaé Foster, with Montrose Center support.","source_urls":["https://montrosecenter.org/","https://www.graceplacehouston.org/"],"updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Q Center","city":"portland","type":"other","provider_name":"Q Center","contact":"Use the official contact and programme forms","booking_link":"https://www.pdxqcenter.org/","description":"Portland's LGBTQIA2S+ community centre offers support, resource navigation, identity-specific groups, sober connection, movement, arts and year-round events. It is a programme hub rather than a single counselling clinic, so the current calendar and group eligibility should guide each visit.","hours":"Programme and event-led; verify office access and registration on the official calendar.","link":"https://www.pdxqcenter.org/","location":"4115 N Mississippi Avenue, Portland, OR 97217, United States","lat":45.55328,"lng":-122.67559,"price_tier":"$","vibe":"steady LGBTQIA2S+ belonging, peer support and resource navigation on Mississippi Avenue","source":"Q Center official services and 2026 programme calendar; checked 2026-08-27","intel":{"booking_lead_time":"Groups and classes use separate registration; resource navigation may require advance contact rather than an unscheduled visit.","best_time":"Choose the exact identity group, support need or public programme and arrive during its published window.","client_mix":"LGBTQIA2S+ adults, youth, trans and non-binary people, sober participants, newcomers and community organisations.","preparation":"Read eligibility and privacy expectations, disclose accessibility needs and confirm whether the event is in person or virtual.","provider_inclusivity":"Q Center is explicitly Portland's LGBTQIA2S+ community centre and frames support around belonging, protection and empowerment.","source_urls":["https://www.pdxqcenter.org/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Prism Health","city":"portland","type":"wellness","provider_name":"Cascade AIDS Project","contact":"503-445-7699","booking_link":"https://www.prismhealth.org/","description":"A primary-care clinic created by Cascade AIDS Project for LGBTQ+ people, offering affirming general care, gender-affirming services, HIV prevention and treatment, behavioural health and pharmacy coordination. Clinical availability and insurance rules should be confirmed directly.","hours":"Weekday clinical schedule by appointment; use current official hours and urgent-care guidance.","link":"https://www.prismhealth.org/","location":"2236 SE Belmont Street, Portland, OR 97214, United States","lat":45.51668,"lng":-122.64373,"price_tier":"$","vibe":"integrated LGBTQ+ primary care grounded in HIV expertise and gender affirmation","source":"Prism Health and Cascade AIDS Project official service pages; checked 2026-08-27","intel":{"booking_lead_time":"New-patient primary care and behavioural health can require advance scheduling; sexual-health timing should be explained when calling.","best_time":"Contact on a weekday with the specific need—PrEP, HIV care, hormones, primary care or mental health—so staff can route accurately.","client_mix":"LGBTQ+ adults, trans and non-binary patients, people living with or preventing HIV and wider community patients seeking affirming care.","preparation":"Bring medication history and insurance details if available; ask about cost, pharmacy, labs, chosen name and telehealth before the visit.","provider_inclusivity":"The clinic was built specifically around LGBTQ+ healthcare and links clinical care to Cascade AIDS Project's community expertise.","source_urls":["https://www.prismhealth.org/","https://www.capnw.org/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Cascade AIDS Project","city":"portland","type":"wellness","provider_name":"Cascade AIDS Project","contact":"503-223-5907","booking_link":"https://www.capnw.org/","description":"A Pacific Northwest HIV organisation providing testing, prevention, housing, insurance navigation, support and community programmes. Services are distributed across teams and sites, so the Davis Street office is an orientation point rather than a guarantee that every service is available as a walk-in.","hours":"Weekday office and programme hours vary; contact the relevant service first.","link":"https://www.capnw.org/","location":"520 NW Davis Street, Suite 215, Portland, OR 97209, United States","lat":45.52453,"lng":-122.67573,"price_tier":"$","vibe":"practical HIV prevention, housing and support backed by long community history","source":"Cascade AIDS Project official programmes and contact page; checked 2026-08-27","intel":{"booking_lead_time":"Testing, housing and case-management routes differ; use the programme contact before arriving at the administrative office.","best_time":"Weekday contact is best, with exposure timing, housing urgency or benefits deadlines stated at the beginning.","client_mix":"People living with or affected by HIV, LGBTQ+ communities, people seeking prevention, housing support and insurance navigation.","preparation":"Bring only documents relevant to the service and ask about confidentiality, fees, test windows and language access.","provider_inclusivity":"Decades of HIV and LGBTQ+ community work and the creation of Prism Health provide direct evidence of specialised competency.","source_urls":["https://www.capnw.org/","https://www.prismhealth.org/"],"updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"CAMP Rehoboth Community Center","city":"rehoboth_beach","type":"other","provider_name":"CAMP Rehoboth","contact":"302-227-5620","booking_link":"https://www.camprehoboth.com/","description":"The year-round LGBTQ+ community centre behind many of Rehoboth's defining programmes, including support, health outreach, arts, advocacy, Women's FEST, SUNFESTIVAL and the Block Party. Its mission explicitly covers all sexual orientations and gender identities across Southern Delaware.","hours":"Office and programme hours vary; use the current calendar and contact the centre before a specific service.","link":"https://www.camprehoboth.com/","location":"37 Baltimore Avenue, Rehoboth Beach, DE 19971, United States","lat":38.71801,"lng":-75.07913,"price_tier":"$","vibe":"year-round queer community infrastructure connecting resort celebration with real local support","source":"CAMP Rehoboth official mission, programme and event pages; checked 2026-08-27","intel":{"booking_lead_time":"Support groups, health programmes, tickets and volunteer services use different routes; contact the relevant programme ahead.","best_time":"Weekday office contact suits referrals, while calendar events and groups may happen evenings or weekends.","client_mix":"LGBTQ+ residents and visitors, women, youth, older adults, people seeking support, volunteers, artists and Southern Delaware allies.","preparation":"Name the programme or need, confirm eligibility and access, and use event-specific ticketing rather than assuming office admission covers it.","provider_inclusivity":"The centre explicitly serves all sexual orientations and gender identities and has operated as Rehoboth's community anchor since 1991.","source_urls":["https://www.camprehoboth.com/","https://give.camprehoboth.org/events/block-party"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Sussex Pride","city":"rehoboth_beach","type":"other","provider_name":"Sussex Pride","contact":"Use the official contact form","booking_link":"https://sussexpride.org/","description":"A countywide LGBTQ+ organisation serving the broader area around Rehoboth through youth support, education, advocacy and community connection. It complements CAMP's Rehoboth base by addressing the reality that many residents live outside the resort core.","hours":"Programme and appointment-led across Sussex County; verify the current contact route.","link":"https://sussexpride.org/","location":"Sussex County service area; contact for current programme location","lat":38.72090,"lng":-75.07600,"price_tier":"$","vibe":"countywide queer youth support and advocacy reaching beyond the visible beach district","source":"Sussex Pride official mission and programme pages; checked 2026-08-27","intel":{"booking_lead_time":"Youth and community programmes require current registration or contact; do not assume a permanent Rehoboth walk-in office.","best_time":"Reach out before travelling and state age group, programme interest, transport and privacy needs.","client_mix":"LGBTQ+ youth, families, educators, residents and allies across Sussex County, including communities outside the resort economy.","preparation":"Use a safe contact method, confirm location and eligibility, and ask about virtual participation when transport is difficult.","provider_inclusivity":"The organisation is explicitly LGBTQ+ and countywide, addressing gaps that a tourism-centred city service can miss.","source_urls":["https://sussexpride.org/"],"updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Southwest Center","city":"phoenix","type":"wellness","provider_name":"Southwest Center","contact":"602-307-5330","booking_link":"https://www.swcenter.org/","description":"A Phoenix LGBTQ+ health and community organisation providing HIV and STI services, PrEP navigation, primary and affirming care, behavioural health, support and community programmes. The shared Parsons Center location links clinical care with youth and advocacy organisations.","hours":"Clinical and programme schedules vary; contact the centre for current appointments and testing windows.","link":"https://www.swcenter.org/","location":"1101 N Central Avenue, Suite 200, Phoenix, AZ 85004, United States","lat":33.46056,"lng":-112.07384,"price_tier":"$","vibe":"integrated LGBTQ+ health, testing and community care in a central shared-services hub","source":"Southwest Center official health and programme pages; checked 2026-08-27","intel":{"booking_lead_time":"Primary care, behavioural health, testing and navigation use separate booking paths; explain exposure or medication timing when calling.","best_time":"Weekday contact with the exact service request is best; same-day testing availability should never be assumed.","client_mix":"LGBTQ+ people, trans and non-binary patients, people living with or preventing HIV and wider Phoenix community members.","preparation":"Bring medication and insurance information if available and ask about sliding fees, confidentiality, lab timing and chosen-name records.","provider_inclusivity":"The centre is explicitly LGBTQ+ and integrates gender-affirming, HIV and behavioural health expertise rather than outsourcing inclusion.","source_urls":["https://www.swcenter.org/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"one-n-ten","city":"phoenix","type":"other","provider_name":"one-n-ten","contact":"602-400-2601","booking_link":"https://onenten.org/","description":"Arizona's LGBTQ+ youth organisation provides social groups, leadership, housing and homelessness support, education and life-skills programmes for young people. The Downtown Phoenix centre is a community and programme site, not an adult visitor attraction.","hours":"Youth programme schedule varies; use the official calendar and intake route.","link":"https://onenten.org/","location":"1101 N Central Avenue, Suite 202, Phoenix, AZ 85004, United States","lat":33.46056,"lng":-112.07384,"price_tier":"$","vibe":"youth-centred queer belonging, leadership and practical stability across Arizona","source":"one-n-ten official youth, housing and programme pages; checked 2026-08-27","intel":{"booking_lead_time":"Groups and support programmes require age-appropriate registration or intake; housing urgency should be stated immediately.","best_time":"Contact during office hours before attending a youth group and confirm age range, transport and guardian requirements.","client_mix":"LGBTQ+ youth and young adults, including trans and non-binary young people and those experiencing housing instability.","preparation":"Use a safe contact method, confirm eligibility and location, and protect youth privacy in all public communication.","provider_inclusivity":"The organisation is built specifically for LGBTQ+ young people and combines community belonging with housing and life-skills support.","source_urls":["https://onenten.org/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Aunt Rita's Foundation","city":"phoenix","type":"wellness","provider_name":"Aunt Rita's Foundation","contact":"602-882-8675","booking_link":"https://auntritas.org/","description":"A statewide HIV organisation headquartered at the Parsons Center, coordinating education, testing access, partner support and the AIDS Walk Arizona fundraising network. It is best used as a connection and mobilisation hub rather than described as a full walk-in medical clinic.","hours":"Weekday office and event schedule; verify testing and partner-service locations.","link":"https://auntritas.org/","location":"1101 N Central Avenue, Suite 212, Phoenix, AZ 85004, United States","lat":33.46056,"lng":-112.07384,"price_tier":"$","vibe":"statewide HIV mobilisation connecting prevention, testing partners and community fundraising","source":"Aunt Rita's official programmes and contact page; checked 2026-08-27","intel":{"booking_lead_time":"Testing and direct care may be delivered by partner organisations; contact first for the correct current site.","best_time":"Weekday routing is best, especially when exposure timing or a benefits deadline affects which service is appropriate.","client_mix":"People affected by HIV, LGBTQ+ communities, prevention clients, volunteers, donors and statewide partner organisations.","preparation":"State whether the need is testing, care linkage, education or event participation and ask which provider owns the next step.","provider_inclusivity":"The foundation's HIV mission and long partnership network are direct community evidence, while clinical scope is accurately limited.","source_urls":["https://auntritas.org/"],"updated_at":"2026-08-27T00:00:00Z"}},

  {"name":"Hawaiʻi Health & Harm Reduction Center","city":"honolulu","type":"wellness","provider_name":"Hawaiʻi Health & Harm Reduction Center","contact":"808-521-2437; info@hhhrc.org","booking_link":"https://www.hhhrc.org/","description":"Hawaiʻi's largest and oldest LGBTQ+ service organisation in the Pacific provides HIV and hepatitis work, harm reduction, care, advocacy, training and support for communities including trans, LGBQ and Native Hawaiian people. It is a broad service hub rather than only a testing site.","hours":"Monday-Friday 09:00-16:30 according to the current official site.","link":"https://www.hhhrc.org/","location":"677 Ala Moana Boulevard, Suite 226, Honolulu, HI 96813, United States","lat":21.29870,"lng":-157.86128,"price_tier":"$","vibe":"Pacific-rooted harm reduction and LGBTQ+ health work combining care, dignity and advocacy","source":"HHHRC official site and Hawaiʻi Department of Health current directory; checked 2026-08-27","intel":{"booking_lead_time":"Testing, care, syringe exchange and training use different routes; call before arriving for a clinical need.","best_time":"Weekday morning contact allows routing before the 16:30 close; state exposure, medication or urgent harm-reduction needs clearly.","client_mix":"Trans and LGBQ people, Native Hawaiian communities, people affected by HIV or hepatitis, people who use drugs and people facing homelessness.","preparation":"Ask about test windows, identification, cost, confidentiality and the exact service location; bring medication information if relevant.","provider_inclusivity":"The organisation explicitly centres transgender, LGBQ and Native Hawaiian communities and has served Hawaiʻi since 1983.","source_urls":["https://www.hhhrc.org/","https://health.hawaii.gov/harmreduction/get-tested/other-testing-locations/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"Diamond Head STI/HIV Clinic","city":"honolulu","type":"wellness","provider_name":"Hawaiʻi State Department of Health","contact":"Appointment line 808-733-9849","booking_link":"https://health.hawaii.gov/harmreduction/get-tested/diamond-head-health-center-sti-hiv-clinic/","description":"A confidential state STI and HIV clinic offering free testing and treatment without requiring health insurance. Its published welcome explicitly includes sexual orientation and gender identity, while walk-ins depend on appointment no-shows and therefore cannot be guaranteed.","hours":"Appointments Monday-Friday 08:30-15:00; patient services Monday-Friday 11:00-16:00 except holidays.","link":"https://health.hawaii.gov/harmreduction/get-tested/diamond-head-health-center-sti-hiv-clinic/","location":"Diamond Head Health Center, 3627 Kilauea Avenue, Suite 305, Honolulu, HI 96816, United States","lat":21.28162,"lng":-157.79904,"price_tier":"$","vibe":"free confidential public sexual healthcare with an explicit non-judgment commitment","source":"Hawaiʻi Department of Health official clinic page; checked 2026-08-27","intel":{"booking_lead_time":"Call for an appointment; same-day walk-in care occurs only when a scheduled patient does not attend and is never guaranteed.","best_time":"Call during the 08:30-15:00 appointment window and describe symptoms or exposure timing for correct testing advice.","client_mix":"Anyone needing STI or HIV testing and treatment, including LGBTQ+ people, uninsured patients and visitors who meet clinic requirements.","preparation":"Be ready to provide contact details confidentially; ask which tests, treatment, identification and follow-up are available.","provider_inclusivity":"The state clinic explicitly welcomes patients regardless of sexual orientation, sex or gender identity and provides care without insurance.","source_urls":["https://health.hawaii.gov/harmreduction/get-tested/diamond-head-health-center-sti-hiv-clinic/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"The LGBTQ+ Center Honolulu","city":"honolulu","type":"other","provider_name":"Hawaiʻi LGBT Legacy Foundation","contact":"Use the Foundation contact page","booking_link":"https://hawaiilgbtlegacyfoundation.com/","description":"A Waikīkī meeting and community space operated by the Hawaiʻi LGBT Legacy Foundation, which also produces Honolulu Pride and year-round educational programmes. The centre hosts organisations and meetings; it should not be described as a walk-in clinical service.","hours":"Meeting and event-led; confirm access with the Foundation before visiting.","link":"https://hawaiilgbtlegacyfoundation.com/","location":"Waikīkī Business Plaza, 2270 Kalākaua Avenue, Suite 1506, Honolulu, HI 96815, United States","lat":21.27912,"lng":-157.82720,"price_tier":"$","vibe":"central Waikīkī community room connecting local organisations, education and Honolulu Pride","source":"Hawaiʻi LGBT Legacy Foundation official centre-use and Pride materials; checked 2026-08-27","intel":{"booking_lead_time":"Meetings and room use require organiser or Foundation coordination; public walk-in hours should not be assumed.","best_time":"Attend a confirmed programme and allow time for Waikīkī Business Plaza lift and building access.","client_mix":"LGBTQIA+ and MVPFAFF+ organisations, community groups, educators, Pride volunteers and meeting participants.","preparation":"Confirm the event, suite access, parking validation and building instructions; respect any meeting privacy requirements.","provider_inclusivity":"The Foundation produces Honolulu Pride and explicitly supports Hawaiʻi's LGBTQIA+ community through year-round programmes and space.","source_urls":["https://hawaiilgbtlegacyfoundation.com/","https://www.honolulupride.com/"],"updated_at":"2026-08-27T00:00:00Z"}},
  {"name":"The Lavender Clinic","city":"honolulu","type":"wellness","provider_name":"The Lavender Clinic","contact":"808-744-2543","booking_link":"https://www.lavendercenterandclinic.org/","description":"An LGBTQIA+-focused Honolulu health provider offering affirming primary and behavioural healthcare with particular relevance to trans and gender-diverse patients. Current appointment, insurance and location details must come from the clinic rather than older community directories.","hours":"Clinical services by appointment; verify current hours and new-patient availability.","link":"https://www.lavendercenterandclinic.org/","location":"1481 S King Street, Honolulu, HI 96814, United States","lat":21.29812,"lng":-157.84129,"price_tier":"$","vibe":"identity-affirming medical and behavioural care designed around Hawaiʻi's LGBTQIA+ communities","source":"Lavender Clinic and Hawaiʻi Department of Health SGM resources; checked 2026-08-27","intel":{"booking_lead_time":"New-patient and specialist availability can vary; contact before travel and explain the care type requested.","best_time":"Weekday contact with medication, hormone, mental-health or primary-care needs stated clearly supports accurate routing.","client_mix":"LGBTQIA+ patients, especially trans and gender-diverse people, alongside anyone seeking affirming primary or behavioural care.","preparation":"Bring medication and insurance information if available and ask about cost, labs, telehealth, records and chosen-name handling.","provider_inclusivity":"The clinic is purpose-built for LGBTQIA+ healthcare and is listed in Hawaiʻi's sexual and gender minority health resources.","source_urls":["https://www.lavendercenterandclinic.org/","https://health.hawaii.gov/harmreduction/sexual-gender-minority-health/"],"updated_at":"2026-08-27T00:00:00Z"}}
]
$qa_us_services$) s(name text,city text,type text,provider_name text,contact text,booking_link text,description text,hours text,link text,location text,lat double precision,lng double precision,price_tier text,vibe text,source text,intel jsonb)
), upd as (
  update public.services s set type=x.type,provider_name=x.provider_name,contact=x.contact,booking_link=x.booking_link,description=x.description,hours=x.hours,
    link=x.link,location=x.location,lat=x.lat,lng=x.lng,price_tier=x.price_tier,vibe=x.vibe,source=x.source,"lastChecked"=date '2026-08-27',
    verified=true,service_intel=x.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
  from src x where lower(trim(s.city))=x.city and lower(trim(s.name))=lower(trim(x.name)) returning s.id
)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,price_tier,vibe,vibe_tags,source,"lastChecked",verified,service_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,price_tier,vibe,array[]::text[],source,date '2026-08-27',true,intel,true,'approved',timezone('utc',now()) from src x
where not exists(select 1 from public.services s where lower(trim(s.city))=x.city and lower(trim(s.name))=lower(trim(x.name)));

