from exact x where lower(trim(t.city))=x.city and lower(trim(t.name))=lower(trim(x.name));


-- Refresh automatic city SEO readiness after every qualifying entity exists.
select public.qa_refresh_city_seo_status(slug)
from (values ('houston'),('portland'),('rehoboth_beach'),('phoenix'),('honolulu')) v(slug);

commit;

-- Human-readable verification result after execution.
select c.slug,c.name,c.verified_place_count,c.seo_indexable,c.seo_requirements
from public.qa_cities c
where c.slug in ('houston','portland','rehoboth_beach','phoenix','honolulu')
order by c.slug;
